/* Plainkit a11y layer: loaded LAST, because these rules must beat the component defaults at equal specificity.
   Keyboard focus ring for every interactive control, tap behaviour, and the phone rules
   (16px inputs so iOS does not zoom on focus; 44px touch targets). */

a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
summary:focus-visible,
[tabindex]:focus-visible {
    outline: var(--focus-ring);
    outline-offset: 2px;
}

button,
a.btn-primary,
a.btn-ghost,
a.btn-warn,
a.btn-secondary,
.tab,
.tab-close,
select,
summary {
    touch-action: manipulation;
}

@media (max-width: 640px) {
    input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]):not([type="file"]),
    select,
    textarea {
        font-size: 16px !important;
    }

    button.btn-primary,
    button.btn-ghost,
    button.btn-warn,
    button.btn-secondary,
    button.btn-mini,
    a.btn-primary,
    a.btn-ghost,
    a.btn-warn,
    a.btn-secondary,
    .tab,
    .tab-close,
    .chip-btn,
    a.btn-mini,
    .snav-link,
    .tnav-link,
    .dropdown-item,
    .page-link,
    .pill,
    .btn-group > *,
    summary,
    select,
    input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]):not([type="file"]) {
        min-height: var(--touch-target);
    }
}

/* Plainkit base: reset, typography, form-control and link baselines. Element selectors only, so a component class always wins. */

* {
    box-sizing: border-box;
}

html, body {
    margin: 0;
    padding: 0;
    height: 100%;
    font-family: var(--font-sans);
    background: var(--color-bg);
    color: var(--color-text);
    font-size: 14px;
}

/* Form-control baseline: themed surface and readable text. Element selectors, so a component class still wins. */

:where(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]):not([type="file"]),
textarea,
select) {
    background: var(--color-input);
    color: var(--color-text);
    border: 1px solid var(--color-input-border);
}

input::placeholder,
textarea::placeholder {
    color: var(--color-muted);
    opacity: 1;   /* Firefox dims placeholders by default; keep them legible */
}

/* Global link baseline, and the same argument as the form controls above: an
   unstyled control inherits the browser's defaults, which were never chosen
   against this palette. A bare <a> rendered in default browser blue — roughly 2.3:1 on the
   dark panel, and the purple :visited variant is worse — which is what the
   "Tools → File importer" links in the order page's cards were doing.

   Scoped with :not([class]) rather than to every anchor on purpose. An anchor
   that carries a class has been dressed deliberately — a.btn-primary, the docs
   nav, the help-flyout footer — and a blanket `a { }` would fight all of them
   over colour and underline. This targets exactly the case that has no answer
   at all. Note it ties on specificity with rules like .docs-body a, so it sits
   here near the top of the file where source order lets those win. */

a:not([class]) {
    color: var(--color-link);
    text-decoration: underline;
    text-underline-offset: 0.15em;
}

a:not([class]):hover {
    color: var(--color-link-hover);
}

.required {
    color: var(--color-required);
}

.form-error {
    color: var(--color-notice-error);
    margin: var(--space-1) 0 var(--space-2) 0;
    font-size: var(--text-md);
}

.muted {
    color: var(--color-muted);
}

[hidden] {
    display: none !important;
}

/* Base rhythm. Every rule is wrapped in :where() so it has ZERO specificity: it gives raw content sensible spacing by default and
   any component or page rule that sets its own margin simply wins. Roles come from tokens.css (--gap-heading, --space-*). */

:where(h1, h2, h3, h4, h5, h6) {
    margin-block: 0 var(--gap-heading);
    line-height: 1.25;
}

:where(p, ul, ol, dl, blockquote, pre, figure, fieldset) {
    margin-block: 0 var(--space-3);
}

:where(p, ul, ol, dl, blockquote, pre, figure, fieldset):last-child {
    margin-block-end: 0;
}

:where(ul, ol) {
    padding-inline-start: var(--space-6);
}

:where(li + li) {
    margin-block-start: var(--space-1);
}

:where(blockquote) {
    padding-inline-start: var(--space-4);
    border-inline-start: 3px solid var(--color-border);
    color: var(--color-muted);
}

:where(pre) {
    padding: var(--space-3);
    background: var(--color-surface-alt);
    border-radius: var(--radius-sm);
    font-size: var(--text-sm);
    white-space: pre-wrap;
    overflow-wrap: anywhere;
}

:where(hr) {
    margin-block: var(--space-4);
    border: 0;
    border-top: 1px solid var(--color-border);
}

:where(fieldset) {
    padding: var(--pad-form-section);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
}

:where(legend) {
    padding-inline: var(--space-1);
    color: var(--color-muted);
}

/* Buttons: one shape, four variants, a mini size and a large one. Works on <button> and <a>. Sizes come from the control height token. */
.btn-primary, .btn-ghost, .btn-warn, .btn-secondary, .btn-mini {
    display: inline-flex; align-items: center; justify-content: center; gap: var(--space-2);
    min-height: var(--ctl-h); padding: var(--space-2) var(--space-4);
    border: 1px solid transparent; border-radius: var(--radius-sm);
    font: inherit; font-size: var(--text-read); font-weight: 500; line-height: 1.3;
    text-decoration: none; white-space: nowrap; cursor: pointer;
    transition: background-color 0.15s, border-color 0.15s, color 0.15s;
}

.btn-primary { background: var(--color-accent); color: var(--btn-primary-fg); }
.btn-primary:hover { background: var(--color-accent-hover); }
a.btn-primary:hover { color: var(--a-btn-primary-hover-fg); }

.btn-ghost { background: transparent; color: var(--field-muted); border-color: var(--color-border); }
.btn-ghost:hover:not(:disabled) { color: var(--color-text); border-color: var(--color-text); }

.btn-warn { background: var(--btn-warn-bg); color: var(--btn-warn-fg); }
.btn-warn:hover:not(:disabled) { background: var(--btn-warn-hover-bg); }

.btn-secondary { background: transparent; color: var(--color-accent); border-color: var(--color-accent); }
.btn-secondary:hover:not(:disabled) { color: var(--color-accent-hover); border-color: var(--color-accent-hover); }

.btn-primary:disabled, .btn-primary[disabled], .btn-ghost:disabled, .btn-ghost[disabled], .btn-warn:disabled, .btn-warn[disabled],
.btn-secondary:disabled, .btn-secondary[disabled] { opacity: 0.45; cursor: not-allowed; }

/* Mini: the 12px desktop-density control; the a11y layer raises it to the touch size on a phone. It is the primary colour unless combined. */
.btn-mini {
    min-height: 0; padding: var(--space-1) var(--space-2); margin-right: var(--space-1);
    background: var(--color-accent); color: var(--btn-mini-fg); font-size: var(--text-meta); font-weight: 400;
}
.btn-mini:hover:not(:disabled) { background: var(--color-accent-hover); }
.btn-mini:disabled { opacity: 0.4; cursor: not-allowed; }
.btn-mini.btn-warn { background: var(--btn-mini-btn-warn-bg); }
.btn-mini.btn-warn:hover:not(:disabled) { background: var(--btn-mini-btn-warn-hover-bg); }
.btn-mini.btn-secondary { background: transparent; border-color: var(--color-accent); color: var(--color-accent); }
.btn-mini.btn-ghost { background: transparent; border-color: var(--color-border); color: var(--field-muted); }
.btn-mini.btn-ghost:hover:not(:disabled) { color: var(--color-text); border-color: var(--color-text); }

/* -------- Cards / buttons -------- */

.card {
    background: var(--color-panel);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    padding: var(--space-4) 1.25rem;
    margin-top: var(--space-4);
    box-shadow: var(--shadow-card);
}

.card.error {
    border-color: var(--card-error-border);
}

/* -------- Card header bar (h2 + inline action button) -------- */

.card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    /* Wrap rather than overflow. A header is a title plus whatever the card
       wants beside it — a sentence, a toggle, a link — and on a narrow column
       that pair does not fit on one line. Pages used to restate this flex row
       as an inline style just to add a gap, which then outranked every
       responsive rule the stylesheet tried to apply to it. */
    flex-wrap: wrap;
    gap: var(--space-3);
    /* A rule under the header, so the card reads as a titled panel rather than
       a bordered box whose first line happens to be bold. Inset to the card's
       own padding rather than bled to its edges: .card-header is used in a
       handful of places that are not inside a .card, and a full-bleed line
       needs negative margins matched to a padding those places do not have. */
    padding-bottom: 0.6rem;
    margin-bottom: 0.9rem;
    border-bottom: 1px solid var(--color-border);
}

.card-header h2 {
    margin: 0;
}

@media (max-width: 640px) {
/* btn-mini exists to be unobtrusive on a dense desktop table; on a phone
       it is a 22px target. Generic selector, so every page's card-header
       buttons get the same floor. */
.card-header .btn-mini { min-height: var(--touch-target); padding: var(--space-2) var(--space-3); font-size: var(--text-base); }
}

/* -------- Line-status chips -------- */

.chip {
    /* inline-flex (not inline-block) so chips with an icon + text
       layout horizontally and align center, regardless of the
       container's font-size. */
    display: inline-flex;
    align-items: center;
    gap: var(--space-1);
    padding: 0.12rem 0.55rem;
    border-radius: var(--radius-pill);
    font-size: var(--text-meta);
    line-height: 1.25;
    background: var(--chip-bg);
    color: var(--chip-fg);
    font-weight: 500;
    /* Pills are atomic — they should never break across two lines.
       In narrow columns the cell can scroll horizontally instead. */
    white-space: nowrap;
    /* Don't let flex parents shrink the chip below its content width. */
    flex-shrink: 0;
    /* Vertically align with surrounding text baselines when used
       inline rather than inside a flex row. */
    vertical-align: middle;
}

.chip strong { font-weight: 700; }

/* A chip that IS the fix, not just the label for it — a <button class="chip
   chip-btn"> keeps the pill and gains the click. Resets only what the button
   element brings with it, so every .chip-* colour still applies. */

.chip-btn {
    border: 0;
    font-family: inherit;
    cursor: pointer;
}

.chip-btn:hover:not(:disabled) { filter: brightness(1.25); }

.chip-btn:focus-visible { outline: var(--focus-ring); }

/* Tones. A status vocabulary maps its own names onto these (see the README). */

.chip-muted { background: var(--chip-bg); color: var(--chip-fg); }

.chip-info { background: var(--chip-info-bg); color: var(--chip-info-fg); }

.chip-success { background: var(--chip-success-bg); color: var(--chip-success-fg); }

.chip-warn { background: var(--chip-warn-bg); color: var(--chip-warn-fg); }

.chip-danger { background: var(--chip-danger-bg); color: var(--chip-danger-fg); }

.chip-accent { background: var(--chip-accent-bg); color: var(--chip-accent-fg); }

/* -------- Cluster (Cluster) -------- */

.cluster {
    display: flex;
}

.cluster--horizontal { flex-direction: row; }

.cluster--vertical { flex-direction: column; }

.cluster--gap-none { gap: 0; }

.cluster--gap-xs { gap: var(--space-1); }

.cluster--gap-sm { gap: var(--space-2); }

.cluster--gap-md { gap: var(--space-4); }

.cluster--gap-lg { gap: var(--space-6); }

.cluster--gap-rx { gap: var(--space-3); }

.cluster.cluster--horizontal { flex-wrap: wrap; }

.cluster.cluster--nowrap { flex-wrap: nowrap; }

.cluster--align-start { align-items: flex-start; }

.cluster--align-center { align-items: center; }

.cluster--align-end { align-items: flex-end; }

.cluster--align-stretch { align-items: stretch; }

.cluster--justify-start { justify-content: flex-start; }

.cluster--justify-center { justify-content: center; }

.cluster--justify-end { justify-content: flex-end; }

.cluster--justify-between { justify-content: space-between; }

/* -------- EmptyState (EmptyState) -------- */

.empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--space-2);
    padding: 2rem var(--space-6);
    text-align: center;
    color: var(--color-muted);
}

.empty-state-icon-wrap {
    margin-bottom: var(--space-1);
    opacity: 0.6;
}

.empty-state-title {
    margin: 0;
    font-weight: 600;
    color: var(--color-text);
    font-size: 1rem;
}

.empty-state-description {
    margin: 0;
    max-width: 40rem;
    font-size: var(--text-md);
    line-height: 1.5;
}

.empty-state-actions {
    display: flex;
    gap: var(--space-2);
    flex-wrap: wrap;
    justify-content: center;
    margin-top: var(--space-2);
}

/* Extras: the smaller controls a page needs beyond the core set. Tokens only; spacing from the role tokens. */

/* ---- forms ---- */
.form-grid { display: grid; gap: var(--gap-field); grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr)); }

.form-grid > * { min-width: 0; }

.field-help { margin: var(--gap-input-help) 0 0; font-size: var(--text-sm); color: var(--color-muted); }

.field-error { margin: var(--gap-input-help) 0 0; font-size: var(--text-sm); color: var(--color-notice-error); }

.is-invalid { border-color: var(--color-notice-error) !important; }

.is-valid { border-color: var(--notice-success) !important; }

.input-group { display: flex; align-items: stretch; }

.input-group > input, .input-group > select { flex: 1 1 auto; min-width: 0; border-radius: 0; }

.input-group > :first-child { border-radius: var(--radius-sm) 0 0 var(--radius-sm); }

.input-group > :last-child { border-radius: 0 var(--radius-sm) var(--radius-sm) 0; }

.input-group-text {
    display: inline-flex;
    align-items: center;
    padding: 0 var(--space-3);
    background: var(--color-surface-alt);
    border: 1px solid var(--color-input-border);
    color: var(--color-muted);
    white-space: nowrap;
}

.switch { display: inline-flex; align-items: center; gap: var(--space-2); cursor: pointer; }

.switch > input {
    appearance: none;
    position: relative;
    flex: none;
    width: 2.25rem;
    height: 1.25rem;
    margin: 0;
    background: var(--color-surface);
    border: 1px solid var(--color-input-border);
    border-radius: var(--radius-pill);
    cursor: pointer;
}

.switch > input::after {
    content: "";
    position: absolute;
    top: 0.1rem;
    left: 0.1rem;
    width: 0.9rem;
    height: 0.9rem;
    background: var(--color-muted);
    border-radius: var(--radius-round);
    transition: transform 0.15s ease;
}

.switch > input:checked { background: var(--color-accent); border-color: var(--color-accent); }

.switch > input:checked::after { transform: translateX(1rem); background: var(--btn-primary-fg); }

input[type="range"] { accent-color: var(--color-accent); width: 100%; }

/* ---- buttons ---- */
.btn-group { display: inline-flex; }

.btn-group > * + * { margin-inline-start: -1px; }

.btn-group > * { border-radius: 0; }

.btn-group > :first-child { border-radius: var(--radius-sm) 0 0 var(--radius-sm); }

.btn-group > :last-child { border-radius: 0 var(--radius-sm) var(--radius-sm) 0; }

/* ---- navigation-ish ---- */
.pagination { display: flex; flex-wrap: wrap; gap: var(--gap-control); margin: 0; padding: 0; list-style: none; }

.pagination > li + li { margin: 0; }

.page-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 2.25rem;
    min-height: 2.25rem;
    padding: 0 var(--space-2);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-sm);
    color: inherit;
    text-decoration: none;
}

.page-link:hover { background: var(--color-surface-alt); }

.page-link[aria-current="page"] { background: var(--color-accent); border-color: var(--color-accent); color: var(--btn-primary-fg); }

.pills { display: flex; flex-wrap: wrap; gap: var(--gap-control); }

.pill { padding: var(--space-1) var(--space-3); border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--color-muted); font: inherit; cursor: pointer; }

.pill.active { background: var(--color-accent); color: var(--btn-primary-fg); }

.stepper { display: flex; flex-wrap: wrap; gap: var(--space-3); margin: 0; padding: 0; list-style: none; counter-reset: step; }

.stepper > li { display: flex; align-items: center; gap: var(--space-2); margin: 0; color: var(--color-muted); counter-increment: step; }

.stepper > li::before {
    content: counter(step);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 1.75rem;
    height: 1.75rem;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-round);
}

.stepper > li.active { color: var(--color-text); font-weight: 600; }

.stepper > li.active::before, .stepper > li.done::before { background: var(--color-accent); border-color: var(--color-accent); color: var(--btn-primary-fg); }

.list-group { margin: 0; padding: 0; list-style: none; border: 1px solid var(--color-border); border-radius: var(--radius-md); overflow: hidden; }

.list-group > li { margin: 0; padding: var(--space-3) var(--space-4); }

.list-group > li + li { border-top: 1px solid var(--color-border); }

.accordion > details { border: 1px solid var(--color-border); border-radius: var(--radius-md); }

.accordion > details + details { margin-block-start: var(--space-2); }

.accordion > details > summary { padding: var(--space-3) var(--space-4); cursor: pointer; font-weight: 600; }

.accordion > details > div { padding: 0 var(--space-4) var(--space-4); }

/* ---- feedback ---- */
.progress { height: 0.5rem; background: var(--color-surface-alt); border-radius: var(--radius-pill); overflow: hidden; }

.progress > span { display: block; height: 100%; background: var(--color-accent); }

.spinner {
    display: inline-block;
    width: 1.25rem;
    height: 1.25rem;
    border: 2px solid var(--color-border);
    border-top-color: var(--color-accent);
    border-radius: var(--radius-round);
    animation: pk-spin 0.7s linear infinite;
}

@keyframes pk-spin { to { transform: rotate(360deg); } }

.skeleton--w-60 { width: 60%; }
.skeleton { display: block; min-height: 1rem; background: var(--color-surface-alt); border-radius: var(--radius-sm); animation: pk-pulse 1.4s ease-in-out infinite; }

@keyframes pk-pulse { 50% { opacity: 0.5; } }

@media (prefers-reduced-motion: reduce) { .spinner, .skeleton { animation: none; } }

.toast {
    display: flex;
    align-items: center;
    gap: var(--space-3);
    padding: var(--space-3) var(--space-4);
    background: var(--color-panel);
    border: 1px solid var(--color-border);
    border-inline-start: 3px solid var(--color-accent);
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-card);
}

.avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    width: 2.25rem;
    height: 2.25rem;
    border-radius: var(--radius-round);
    background: var(--color-accent);
    color: var(--btn-primary-fg);
    font-size: var(--text-md);
    font-weight: 600;
}

.timeline { margin: 0; padding: 0 0 0 var(--space-4); list-style: none; border-inline-start: 2px solid var(--color-border); }

.timeline > li { position: relative; margin: 0; padding-block-end: var(--space-4); }

.timeline > li::before {
    content: "";
    position: absolute;
    left: calc(-1 * var(--space-4) - 5px);
    top: 0.35rem;
    width: 0.5rem;
    height: 0.5rem;
    border-radius: var(--radius-round);
    background: var(--color-accent);
}

/* ---- text ---- */
kbd {
    padding: 0.1rem var(--space-2);
    border: 1px solid var(--color-border);
    border-bottom-width: 2px;
    border-radius: var(--radius-sm);
    background: var(--color-surface-alt);
    font-family: ui-monospace, Consolas, monospace;
    font-size: var(--text-sm);
}

.divider { height: 1px; margin-block: var(--space-4); background: var(--color-border); border: 0; }

.tip { position: relative; }

.tip[data-tip]:hover::after,
.tip[data-tip]:focus-visible::after {
    content: attr(data-tip);
    position: absolute;
    left: 50%;
    bottom: calc(100% + var(--space-1));
    transform: translateX(-50%);
    padding: var(--space-1) var(--space-2);
    background: var(--color-flyout);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-sm);
    box-shadow: var(--shadow-card);
    font-size: var(--text-sm);
    white-space: nowrap;
    z-index: var(--z-sticky);
}

/* -------- Upload acknowledgement --------
   One line under the button saying the selection was accepted. The per-file
   tick-or-cross list that used to live here went with the per-file loop: an
   import is a job now, and what the run did is reported by .job-panel. */

.upload-accepted {
    margin-top: 0.6rem;
    font-size: var(--text-read);
}

/* -------- Flyout panel -------- */

.flyout-backdrop {
    position: fixed;
    inset: 0;
    background: var(--flyout-backdrop-bg);
    z-index: var(--z-flyout-backdrop);
}

.flyout-panel {
    position: fixed;
    top: 0;
    right: 0;
    z-index: var(--z-flyout); /* above backdrop */
    background: var(--color-flyout);
    border-left: 1px solid var(--color-border);
    width: min(720px, 90vw);
    height: 100vh;
    height: 100dvh;      /* keeps the sticky footer above Safari's toolbar */
    display: flex;
    flex-direction: column;
    box-shadow: var(--shadow-flyout);
    animation: flyout-slide-in 160ms ease-out;
}

/* Drag handle — covers the left edge of the flyout panel. Invisible by
   default; shows a subtle highlight and ew-resize cursor on hover so the
   operator knows they can resize. */

.flyout-resize-handle {
    position: absolute;
    top: 0;
    left: 0;
    width: 6px;
    height: 100%;
    cursor: ew-resize;
    z-index: var(--z-sticky);
    border-left: 2px solid transparent;
    transition: border-color 120ms ease;
}

.flyout-resize-handle:hover {
    border-left-color: var(--color-accent);
}

@keyframes flyout-slide-in {
    from { transform: translateX(100%); }
    to   { transform: translateX(0); }
}

.flyout-panel--wide {
    width: min(1200px, 70vw);
}

@media (max-width: 640px) {
.flyout-panel,
    .flyout-panel--wide { width: 100vw; border-left: none; }
.flyout-resize-handle { display: none; }
}

@media (max-width: 640px) {
.flyout-panel--phone-cards { box-shadow: none; }
/* NOT sticky. It was, and on a real phone that painted the header over the
       first row of the body: the owner could not see or tap the Status picker at
       the top of the product page's Actions sheet (2026-09-18). Emulation never
       showed it, scrolled or not.

       Sticky bought nothing here. The header is not inside the scroller -- it
       sits above .flyout-body in the panel's flex column, and the BODY is what
       scrolls -- so it already stays put. What sticky did add was a scroll
       container lookup, and the nearest DOM ancestor with overflow is the
       page's own .page-body, which the operator has usually scrolled before
       tapping Actions. A position:fixed panel is meant to break that ancestry;
       an engine that does not treat it so offsets the header against the page's
       scroll, and z-index plus an opaque background then paint it over whatever
       is first in the body. A plain flex item cannot overlap its sibling in any
       engine, so the mechanism is gone rather than tuned. */
.flyout-panel--phone-cards .flyout-header {
        position: relative;
        flex: none;
        padding: 0.55rem var(--space-3) 0.55rem var(--space-4);
        background: var(--color-flyout);
    }
.flyout-panel--phone-cards .flyout-close {
        min-width: 2.5rem;
        min-height: 2.5rem;
    }
.flyout-panel--phone-cards .flyout-body {
        padding: var(--space-3);
        background: var(--color-bg);
        /* The body is the scroller, so it has to be allowed to be shorter than
           its content. A flex item defaults to min-height:auto -- its content
           height -- which on a phone with the browser toolbar showing (100dvh is
           shorter) lets the panel's content outgrow the panel instead of
           scrolling inside it. */
        min-height: 0;
        /* A drag on a short sheet has nothing to scroll here and would otherwise
           chain out and scroll the page behind the backdrop. */
        overscroll-behavior: contain;
    }
}

.flyout-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--space-3) 1.25rem;
    border-bottom: 1px solid var(--color-border);
}

.flyout-header h2 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 600;
}

.flyout-close {
    font-size: 1rem;
}

/*
 * Action bar inside a flyout. FlyoutPanel owns this layout so every
 * module's flyout gets the same look — no per-page drift on button
 * spacing or sizing. Color variants (btn-primary, btn-warn, btn-ghost)
 * still come from the button's class; the size is forced here.
 */

.flyout-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-3) 1.25rem;
    border-bottom: 1px solid var(--color-border);
    background: var(--flyout-body-muted-bg);
}

.flyout-actions button,
.flyout-actions a.btn,
.flyout-actions a.btn-primary {
    /* Uniform size inside the action bar, regardless of btn-primary vs btn-mini. */
    padding: 0.35rem 0.85rem;
    font-size: var(--text-md);
    font-weight: 500;
    border-radius: var(--radius-sm);
    margin: 0;
    line-height: 1.3;
}

.flyout-actions .muted,
.flyout-actions .form-error {
    /* Status text (last-sync info, errors) sits alongside the buttons. */
    font-size: var(--text-read);
    line-height: 1.3;
    margin: 0;
}

.flyout-body {
    padding: var(--space-4) 1.25rem;
    overflow-y: auto;
    /* overflow-x: auto + min-width: 0 lets wide inline content (data
       tables, code blocks, long URLs) get a horizontal scrollbar
       within the flyout instead of pushing the panel wider than the
       viewport. The min-width: 0 is the classic flex-shrink trick —
       without it, flex children inherit min-width: auto (= intrinsic
       content width) and refuse to shrink below their widest child. */
    overflow-x: auto;
    min-width: 0;
    flex: 1;
    /* Container query context for content inside the flyout body. */
    container-type: inline-size;
    container-name: flyout-body;
}

.flyout-footer {
    padding: var(--space-3) 1.25rem;
    border-top: 1px solid var(--color-border);
}

/* Loading overlay inside a flyout body */

.flyout-body--loading {
    position: relative;
    pointer-events: none;   /* block all clicks through to child content */
}

.flyout-loading-overlay {
    position: absolute;
    inset: 0;
    background: var(--flyout-loading-overlay-bg); /* matches --color-flyout at 55% */
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: var(--z-sticky);
    border-radius: 0 0 var(--radius-sm) var(--radius-sm);
}

.flyout-spinner {
    width: 2rem;
    height: 2rem;
    border: 3px solid var(--color-input-border);
    border-top-color: var(--flyout-spinner-accent);
    border-radius: var(--radius-round);
    animation: flyout-spin 0.65s linear infinite;
}

@keyframes flyout-spin {
    to { transform: rotate(360deg); }
}

/* Dim action bar buttons while the body is loading */

.flyout-actions--loading {
    opacity: 0.45;
    pointer-events: none;
