/* Lighter input surfaces inside flyouts */

.flyout-body input[type="text"],
.flyout-body input[type="number"],
.flyout-body input[type="url"],
.flyout-body input[type="date"],
.flyout-body input[type="search"],
.flyout-body input[type="email"],
.flyout-body select,
.flyout-body textarea {
