// Unit tests for the local-date-time component.
import test from 'node:test';
import assert from 'node:assert/strict';
import { formatLocal } from './local-date-time.js';

test('formatLocal formats an ISO instant in the given locale, date only on request, and passes bad input through', () => {
    assert.equal(formatLocal('2026-09-19T14:30:00Z', 'date', 'en-US'), new Date('2026-09-19T14:30:00Z').toLocaleDateString('en-US'));
    assert.equal(formatLocal('2026-09-19T14:30:00Z', 'datetime', 'en-US'), new Date('2026-09-19T14:30:00Z').toLocaleString('en-US'));
    assert.equal(formatLocal('not a date'), 'not a date');
});

/* Maintenance tab on Data Explorer — collapsible category sections,
   each holding a 3-up grid of maintenance cards. Also used in flyout
   panels (Products, etc.) as visually-distinct collapsible sections. */

.maint-section {
    margin: 0.5rem 0 1rem 0;
    background: var(--color-input);
    border: 1px solid var(--color-input-border);
    border-radius: 6px;
    /* overflow:hidden removed — it clips position:absolute InfoTip panels
       even at z-index:9000. Top-corner rounding is handled by the header. */
}

/* THE WHOLE ROW IS THE TAP TARGET, not the arrow .
   ──────────────────────────────────────────────────────────────────────
   The arrow is a ~10px glyph, and on a phone nobody aims at a 10px glyph:
   they press the words. <summary> already accepts the press anywhere along
   its box, so the job is to make that box big enough to hit and legible
   enough to read at arm's length. 44px is the usual minimum for a touch
   target and this row had ~35px of it.

   min-height rather than a taller padding alone, so a section whose title
   wraps to two lines grows instead of squashing, and flex-wrap so a long
   title plus an InfoTip drops to a second line rather than pushing the
   header wider than its card — an element wider than the viewport does not
   clip, it widens .page-body and side-scrolls the whole page.

   One rule for every collapsible: they all use .maint-section, so this is
   changed here and nowhere else.
   ────────────────────────────────────────────────────────────────────── */

.maint-section-header {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.5rem;
    min-height: 44px;
    padding: 0.55rem 0.85rem;
    margin: 0;
    list-style: none;
    cursor: pointer;
    font-size: 1.05rem;
    font-weight: 600;
    border-radius: 6px 6px 0 0;
    border-bottom: 1px solid var(--color-input-border);
    background: var(--maint-section-header-bg);
    /* A summary is pressed, not read word by word — without this a
       double-tap to open one selects its title instead. */
    user-select: none;
    -webkit-tap-highlight-color: transparent;
}

.maint-section-header:hover {
    background: var(--maint-section-header-hover-bg);
}

/* Keyboard users get the same affordance the pointer gets. */

.maint-section-header:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: -2px;
}

/* Hide the default disclosure marker; use a CSS arrow that flips on open. */

.maint-section-header::-webkit-details-marker { display: none; }

.maint-section-header::marker { content: ""; }

.maint-section-header::before {
    content: "▸";
    display: inline-block;
    /* Fixed box so every section's title starts at the same x whether the
       arrow is pointing right or down, and so it never shrinks when the
       header wraps. */
    flex: 0 0 auto;
    width: 1em;
    text-align: center;
    transition: transform 0.15s ease;
    /* Was --color-muted, which on the dark theme is a grey triangle on a
       grey bar — the "symbols are tough to see" half of the complaint. */
    color: var(--color-text);
    font-size: 1.15em;
    line-height: 1;
}

.maint-section[open] > .maint-section-header::before {
    transform: rotate(90deg);
}

@media (max-width: 640px) {
    .maint-section-header {
        min-height: 48px;
        padding: 0.7rem 0.85rem;
        font-size: 1.1rem;
    }
    .maint-section-header::before {
        font-size: 1.3em;
