/* ── Modal ───────────────────────────────────────────────────────────
   A modal is dismissed by interacting with it — never by clicking the
   backdrop. These carry half-filled forms, and losing a typed record to a
   stray click is the kind of small betrayal that stops people trusting the
   app. Every modal gets a Cancel; the backdrop is inert.

   Centred rather than top-anchored, and the page behind is dimmed AND
   blurred so the modal reads as the only live thing on screen. */

.modal-overlay {
    position: fixed; inset: 0;
    background: var(--modal-overlay-bg);
    /* Progressive: browsers without it still get the dim. */
    backdrop-filter: blur(3px);
    -webkit-backdrop-filter: blur(3px);
    display: flex; align-items: center; justify-content: center;
    z-index: var(--z-modal); padding: var(--space-4);
}

/* A modal raised over an open FlyoutPanel (1501). The condition-map form asks
   "this replaces an existing rule — overwrite?" without closing the flyout
   behind it, so the answer arrives next to the form it is about. */

.modal-overlay--over-flyout { z-index: var(--z-modal-over-flyout); }

.modal-card {
    /* No --t-bg (plain modal) → the theme panel colour, so the card is solid and
       readable in both themes (dark card + light text in dark mode). The tinted
       variants below override --t-bg with a fixed light wash + force dark text. */
    background: var(--t-bg, var(--color-panel));
    color: var(--color-text);
    border: 1.5px solid var(--t-bd, var(--color-border));
    border-radius: var(--radius-xl); padding: 1.25rem var(--space-6);
    width: min(560px, 92vw); max-height: 88vh; overflow-y: auto;
    box-shadow: var(--shadow-modal);
}

/* No fixed "wide" class: every caller goes through the Modal component
   component now, which sets its own inline width from MaxWidthPx. */

.modal-card.t-product { --t-bg: var(--modal-card-t-product-bg); --t-bd: var(--modal-card-t-product-bd); color: var(--modal-card-t-product-fg); }

.modal-card.t-archived { --t-bg: var(--modal-card-t-archived-bg); --t-bd: var(--modal-card-t-archived-bd); color: var(--modal-card-t-archived-fg); }

@media (max-width: 640px) {
.modal-overlay { padding: 0; align-items: stretch; }
.modal-card {
        width: 100%; max-width: none;
        height: 100vh; height: 100dvh; max-height: none;
        border-radius: 0;
        display: flex; flex-direction: column;
    }
.modal-card .card-header { flex: none; }
.modal-card .modal-body { flex: 1 1 auto; min-height: 0; overflow-y: auto; }
.modal-card .modal-footer { flex: none; }
}

.modal-footer {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2);
    margin-top: var(--space-4);
}

.modal-footer--end {
    justify-content: flex-end;
}

// Plainkit overlay behaviour: Escape closes, focus is trapped while open and restored on close,
// and the element gets the dialog semantics. Framework-free; no imports.
//
// Vanilla use: put data-pk-overlay on a .modal-card or .flyout-panel, toggle its `hidden` attribute (or the
// data-pk-open attribute on a trigger: data-pk-open="#id"), and call initOverlays() once.
// Host-framework use: attachOverlay(element, { onClose }) and call the returned detach() when it goes away.

const FOCUSABLE = [
    'a[href]',
    'button:not([disabled])',
    'input:not([disabled]):not([type="hidden"])',
    'select:not([disabled])',
    'textarea:not([disabled])',
    '[tabindex]:not([tabindex="-1"])',
    'summary',
].join(',');

const stack = [];
let listening = false;
let idCounter = 0;

export function focusableWithin(root) {
    return Array.from(root.querySelectorAll(FOCUSABLE)).filter(el => !el.hidden && el.getClientRects().length > 0);
}

// Where Tab should land. Pure so it can be tested without a DOM: index of the focused element in the
// focusable list (-1 = outside), the list length, and whether Shift is held. Returns the index to focus,
// or null to let the browser move focus normally.
export function tabTarget(activeIndex, count, shift) {
    if (count === 0) return -1;
    if (activeIndex === -1) return shift ? count - 1 : 0;
    if (shift && activeIndex === 0) return count - 1;
    if (!shift && activeIndex === count - 1) return 0;
    return null;
}

function onKeydown(event) {
    const top = stack.findLast(entry => entry.holdFocus);
    if (!top) return;

    if (event.key === 'Escape') {
        event.stopPropagation();
        top.onClose?.();
        return;
    }

    if (event.key !== 'Tab') return;
    const items = focusableWithin(top.element);
    const target = tabTarget(items.indexOf(document.activeElement), items.length, event.shiftKey);
    if (target === null) return;
    event.preventDefault();
    (target === -1 ? top.element : items[target]).focus();
}

function ensureLabel(element) {
    if (element.hasAttribute('aria-label') || element.hasAttribute('aria-labelledby')) return;
    const heading = element.querySelector('h1, h2, h3, [data-pk-title]');
    if (!heading) return;
    if (!heading.id) heading.id = `pk-title-${++idCounter}`;
    element.setAttribute('aria-labelledby', heading.id);
}

export function attachOverlay(element, options = {}) {
    if (!element) return { detach() {} };
    const restoreTo = document.activeElement;

    // holdFocus:false is for a docked or backdrop-less inspector that leaves the page usable: no focus hold, no Escape capture, no aria-modal.
    const holdFocus = options.holdFocus !== false;
    // A modal's outer .modal-overlay is only the dimmed backdrop; the dialog is the card inside it.
    const dialog = element.querySelector(':scope > .modal-card') ?? element;
    if (!dialog.hasAttribute('role')) dialog.setAttribute('role', 'dialog');
    if (holdFocus) dialog.setAttribute('aria-modal', 'true');
    ensureLabel(dialog);
    if (!element.hasAttribute('tabindex')) element.setAttribute('tabindex', '-1');

    const entry = { element, onClose: options.onClose, holdFocus };
    stack.push(entry);
    if (!listening) {
        document.addEventListener('keydown', onKeydown, true);
        listening = true;
    }

    if (holdFocus) {
        const autofocus = element.querySelector('[autofocus]');
        (autofocus ?? focusableWithin(element)[0] ?? element).focus({ preventScroll: true });
    }

    return {
        detach() {
            const at = stack.indexOf(entry);
            if (at >= 0) stack.splice(at, 1);
            if (stack.length === 0 && listening) {
                document.removeEventListener('keydown', onKeydown, true);
                listening = false;
            }
            if (holdFocus && restoreTo && restoreTo.isConnected && typeof restoreTo.focus === 'function') restoreTo.focus({ preventScroll: true });
        },
    };
}

// Bridge for a host framework: `remote` is any object with invokeMethodAsync('Close'), called when Escape closes the overlay.
export function attachRemote(element, remote, options = {}) {
    return attachOverlay(element, { ...options, onClose: () => remote.invokeMethodAsync('Close') });
}

// Vanilla wiring: an element with data-pk-overlay is "open" while it is not [hidden]; a data-pk-open
// trigger shows its target, a data-pk-close control (or Escape) hides the nearest overlay.
export function initOverlays(root = document) {
    const handles = new WeakMap();

    // A flyout panel's backdrop is the sibling before it; it shows and hides with the panel.
    const backdrop = el => { const b = el.previousElementSibling; return b?.classList.contains('flyout-backdrop') ? b : null; };
    const show = el => {
        if (!el || !el.hidden) return;
        el.hidden = false;
        const bd = backdrop(el); if (bd) bd.hidden = false;
        handles.set(el, attachOverlay(el, { onClose: () => hide(el) }));
    };
    const hide = el => {
        if (!el || el.hidden) return;
        el.hidden = true;
        const bd = backdrop(el); if (bd) bd.hidden = true;
        handles.get(el)?.detach();
        handles.delete(el);
    };

    root.addEventListener('click', event => {
        const opener = event.target.closest('[data-pk-open]');
        if (opener) {
            show(root.querySelector(opener.getAttribute('data-pk-open')));
            return;
        }
        if (event.target.closest('[data-pk-close]')) hide(event.target.closest('[data-pk-overlay]'));
    });

    root.querySelectorAll('[data-pk-overlay]').forEach(el => { el.hidden = true; });
}

// Unit tests for the modal component's behaviour, run against the fake DOM. Run: node --test sdk
import test from 'node:test';
import assert from 'node:assert/strict';
import { createDocument, el, FakeEvent } from '../../tests/fake-dom.mjs';
import { attachOverlay, tabTarget } from './modal.js';

test('overlay: focus moves in, Escape calls onClose, and detach returns focus to the opener', () => {
    const doc = createDocument();
    globalThis.document = doc;
    const opener = el(doc, 'button'); doc.documentElement.append(opener); opener.focus();
    const inner = el(doc, 'button');
    inner.getClientRects = () => [1];
    const dialog = el(doc, 'div.modal-card', {}, inner);
    dialog.getClientRects = () => [1];
    const overlay = el(doc, 'div.modal-overlay', {}, dialog);
    doc.documentElement.append(overlay);
    let closed = 0;
    const handle = attachOverlay(overlay, { onClose: () => { closed++; } });
    assert.equal(dialog.getAttribute('role'), 'dialog');
    assert.equal(dialog.getAttribute('aria-modal'), 'true');
    doc._listeners.get('keydown')[0](new FakeEvent('keydown', { key: 'Escape' }));
    assert.equal(closed, 1);
    handle.detach();
    assert.equal(doc.activeElement, opener);
    delete globalThis.document;
});

test('overlay: a docked overlay (holdFocus false) claims neither aria-modal nor Escape', () => {
    const doc = createDocument();
    globalThis.document = doc;
    const panel = el(doc, 'div.flyout-panel');
    doc.documentElement.append(panel);
    let closed = 0;
    const handle = attachOverlay(panel, { holdFocus: false, onClose: () => { closed++; } });
    assert.equal(panel.getAttribute('aria-modal'), null);
    doc._listeners.get('keydown')?.[0]?.(new FakeEvent('keydown', { key: 'Escape' }));
    assert.equal(closed, 0);
    handle.detach();
    delete globalThis.document;
});

test('overlay: tabTarget still wraps (regression guard beside the wiring tests)', () => {
    assert.equal(tabTarget(2, 3, false), 0);
});

