.notice-title { margin-right: 0.35rem; }

.notice-dismiss {
    float: right; margin-left: var(--space-2); padding: 0 var(--space-1);
    background: none; border: 0; color: inherit; font-size: 1rem; line-height: 1; cursor: pointer;
}

/* -------- SectionHeader (SectionHeader) --------
 *
 * Title (+ its ⓘ) and the section's own controls share the top line; a note
 * takes a full-width line under both. Cards used to do this by hand — a
 * paragraph given flex:1 that ate the title's row, a button pushed over with
 * an inline margin-left:auto that stopped aligning the moment the header
 * wrapped — so each card header sat differently from the last. */

.section-header-title {
    margin: 0;
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    min-width: 0;
}

/* margin-left:auto rather than justify-content on the parent: the parent also
   holds the note, which must start at the left edge of its own line. */

.section-header-actions {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-left: auto;
    flex-wrap: wrap;
}

.section-header-note {
    flex: 1 1 100%;
    margin: 0;
    font-size: var(--text-read);
    color: var(--color-muted);
}

/* -------- PageHeader (PageHeader) -------- */

.page-header {
    padding: 0.25rem 0;
}

.page-header-titlebar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    flex-wrap: wrap;
}

.page-header-actions {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

@media (max-width: 640px) {
    .page-header-actions {
        width: 100%;
    }
    .page-header-actions > .btn-primary,
    .page-header-actions > .btn-ghost,
    .page-header-actions > .btn-secondary {
        flex: 1 1 auto;
        min-height: 44px;
    }
}

/* Breadcrumbs: where this page sits, small enough to ignore once you know. */

.page-crumbs {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.3rem;
    font-size: var(--text-meta);
    color: var(--page-crumbs-fg);
}

.page-crumbs a {
    color: inherit;
    text-decoration: none;
}

.page-crumbs a:hover {
    text-decoration: underline;
}

.page-crumbs-sep {
    opacity: 0.55;
}

/* The page itself. Not a link, and not louder than the title below it. */

.page-crumbs-current {
    color: var(--color-text, inherit);
}


.section-header { min-width: 0; }

/* Record header: the compact strip at the top of a single-record page. Identifying chips on the left (the back button and title live in the top bar), actions pushed right. */

.record-header {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    width: 100%;
    min-width: 0;
}

.record-header-title {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    flex-wrap: wrap;
}

.record-header-actions {
    display: inline-flex;
    flex-wrap: wrap;
    gap: 0.4rem;
    margin-left: auto;
}

@media (max-width: 1024px) {
    .record-header { flex-wrap: wrap; row-gap: 0.4rem; }
}

@media (max-width: 640px) {
    .record-header { flex-wrap: nowrap; row-gap: 0; }
}

/* -------- Remedy (Remedy) --------
   A message and the control that fixes it, on one line. The action is pushed
   to the end rather than sitting after the full stop, because a button that
   flows with the prose reads as part of the sentence and gets skimmed past.
   On a phone the two stack, message first — the fix is never the thing that
   scrolls off the top. */

.remedy {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    flex-wrap: wrap;
    padding: 0.55rem 0.7rem;
    margin: 0.5rem 0;
    border-left: 3px solid var(--remedy-border);
    border-radius: 0 4px 4px 0;
    background: var(--color-surface-alt);
    font-size: var(--text-read);
    line-height: 1.45;
}

.remedy-body {
    flex: 1 1 16rem;
    min-width: 0;
}

.remedy-actions {
    display: flex;
    gap: 0.4rem;
    flex-wrap: wrap;
    margin-left: auto;
}

.remedy--error { border-left-color: var(--remedy-error-border); }

.remedy--info { border-left-color: var(--color-accent); }

/* App shell and layout primitives. The shell is a grid: side nav + main column (top bar, body, footer). One scroller only: .shell-body.
   Variants: .shell (side nav, default), .shell--top (top navbar over the main column), .shell--center (a centred page such as sign-in). */

.shell {
    display: grid;
    grid-template-columns: var(--shell-nav-w) minmax(0, 1fr);
    height: 100vh;
    height: 100dvh;
    background: var(--color-bg);
    color: var(--color-text);
}

.shell--top {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
}

.shell--collapsed { grid-template-columns: var(--shell-nav-w-collapsed) minmax(0, 1fr); }

.shell--center {
    grid-template-columns: minmax(0, 1fr);
    place-items: center;
    overflow-y: auto;
}

.shell-main {
    display: flex;
    flex-direction: column;
    min-width: 0;
    min-height: 0;
    overflow: hidden;
}

.shell-body {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: var(--space-6);
}

.shell-footer {
    flex: none;
    display: flex;
    align-items: center;
    gap: var(--space-3);
    min-height: var(--app-footer-h);
    padding: 0 var(--space-4);
    background: var(--color-panel);
    border-top: 1px solid var(--color-border);
    font-size: var(--text-sm);
    color: var(--color-muted);
}

.shell-footer-end { margin-left: auto; }

.shell-backdrop { display: none; }

@media (max-width: 1024px) {
    .shell,
    .shell--collapsed { grid-template-columns: minmax(0, 1fr); }

    .shell--nav-open .shell-backdrop {
        display: block;
        position: fixed;
        inset: 0;
        z-index: var(--z-flyout-backdrop);
        background: var(--flyout-backdrop-bg);
    }
}

@media (max-width: 640px) {
    .shell-body { padding: var(--space-4); }
}

/* ---- layout primitives ---- */

.container { width: 100%; max-width: 72rem; margin-inline: auto; }

.container--narrow { max-width: 40rem; }

.grid { display: grid; gap: var(--space-4); grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr)); }

.grid > * { min-width: 0; }

.split { display: grid; gap: var(--space-4); grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); }

.split > * { min-width: 0; }

.split--even { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }

@media (max-width: 1024px) {
    .split,
    .split--even { grid-template-columns: minmax(0, 1fr); }
}

.sticky-header.form-savebar { top: auto; bottom: 0; border-top: 1px solid var(--color-border); border-bottom: 0; padding: var(--space-3) 0; }
.sticky-header {
    position: sticky;
    top: 0;
    z-index: var(--z-sticky);
    background: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
}

/* A centred single card page (sign-in, error). */
.shell--center > .card { width: min(26rem, calc(100% - 2rem)); }

/* A body that owns the whole area (a workspace): no padding, no scroll of its own; the workspace inside scrolls its panes. */
.shell-body--fill {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    padding: 0;
}

/* A shell that fills its container instead of the viewport (a page inside a site frame). */
.shell--fill { height: auto; flex: 1; min-height: 0; }

/* Whatever the fill body holds stretches to it, so a workspace reaches the bottom of the viewport. */
.shell-body--fill > * { display: flex; flex-direction: column; flex: 1; min-height: 0; }

