/* Page-level styling for the raw table slotted into <pk-table> (and the DataGrid chrome around it). The table is light DOM, so shadow CSS cannot
   reach its cells; these rules are keyed by the tag. The frame, toolbar slot and scrolling are in the element's shadow root. Tokens only. */
pk-table {
    & table { inline-size: 100%; border-collapse: collapse; font-size: var(--text-base); }
    & :is(th, td) { padding: var(--pad-cell); border-block-end: 1px solid var(--color-border); text-align: start; }
    & th { color: var(--color-muted); font-size: var(--text-meta); font-weight: 500; letter-spacing: 0.05em; text-transform: uppercase; }
    & :is(th, td).num { text-align: end; font-variant-numeric: tabular-nums; }
    & td code { padding: 0.1rem 0.4rem; border-radius: var(--radius-xs); background: var(--color-bg); font-size: var(--text-md); }
    & th[aria-sort] { cursor: pointer; user-select: none; }
    & th[aria-sort="ascending"]::after { content: " \2191"; }
    & th[aria-sort="descending"]::after { content: " \2193"; }
    &[striped] tbody tr:nth-child(even), &[hover] tbody tr:hover { background: var(--color-surface-alt); }
    &[density="compact"] :is(th, td) { padding: var(--space-1) var(--space-2); }
    &[sticky-header] thead th { position: sticky; inset-block-start: 0; z-index: var(--z-sticky); background: var(--color-panel); }
    & tr[aria-selected="true"] { background: var(--ft-selected-bg); }
    & tr.dg-clickable { cursor: pointer; &:hover { background: var(--dg-clickable-hover-bg); } }
    & .dg-sortable { cursor: pointer; user-select: none; &:hover { color: var(--dg-sortable-hover-fg); } }
    & .dg-select-cell { inline-size: 2.25rem; text-align: center; padding-inline: var(--space-2); }
    & :is(tfoot th, tfoot td) { font-weight: 600; }
}

/* A DataGrid: tighter cells, a per-column filter row, and the toolbar and pager chrome. */
pk-table.dg-body {
    &::part(toolbar) { display: block; margin: 0; }
    & tbody td { padding: 0.35rem var(--space-2); font-size: var(--text-read); }
    & thead th { padding: 0.4rem var(--space-2); font-size: var(--text-meta); font-weight: 600; letter-spacing: 0.02em; }
    & .dg-filterrow th { padding: 0.15rem 0.3rem; border-block-start: 1px solid var(--color-border); background: var(--color-panel); font-weight: normal; }
    & .dg-filter-input { inline-size: 100%; padding: 0.2rem 0.35rem; border: 1px solid var(--color-border); border-radius: var(--radius-xs); background: var(--color-bg); color: inherit; font-size: var(--text-meta); }
}

@media (max-width: 640px) {

    /* a table grid: rows scroll in a bounded frame, the header and the identity column stay put */
    pk-table.dg-body {
        &:has(table:not(.dg-cards)) { --pk-table-max-height: max(14rem, calc(100dvh - var(--app-header-h) - var(--app-footer-h) - 16rem)); }
        &::part(scroll) { overscroll-behavior: contain; }
        & :is(th, td) { padding: var(--space-2); }
        & table:not(.dg-cards) {
            & :is(th, td):first-child, & .dg-select-cell + :is(th, td) { position: sticky; inset-inline-start: 0; z-index: 2; background: var(--color-panel); box-shadow: inset -1px 0 0 var(--color-border); }
            & .dg-select-cell + :is(th, td) { inset-inline-start: 2.5rem; }
            & thead { position: sticky; inset-block-start: 0; z-index: 5; background: var(--color-panel); }
            & thead th { position: relative; z-index: 3; background: var(--color-panel); }
            & thead > tr:last-child > th { box-shadow: inset 0 -1px 0 var(--color-border); }
            & thead :is(th:first-child, .dg-select-cell + th) { position: sticky; z-index: 4; box-shadow: inset -1px 0 0 var(--color-border), inset 0 -1px 0 var(--color-border); }
            & tfoot :is(th, td) { position: sticky; inset-block-end: 0; z-index: 3; background: var(--color-panel); box-shadow: inset 0 1px 0 var(--color-border); }
            & tbody td { white-space: normal; overflow-wrap: anywhere; &:not(.num) { min-inline-size: 5rem; } &.num { white-space: nowrap; overflow-wrap: normal; } &:first-child, &.dg-select-cell + td { min-inline-size: 7rem; max-inline-size: 11rem; } }
        }
        /* columns a page marks HideOnPhone (the grid adds dg-ph-N for the 1-based position) */
        & table.dg-ph-2 :is(th, td):nth-child(2),
        & table.dg-ph-3 :is(th, td):nth-child(3),
        & table.dg-ph-4 :is(th, td):nth-child(4),
        & table.dg-ph-5 :is(th, td):nth-child(5),
        & table.dg-ph-6 :is(th, td):nth-child(6),
        & table.dg-ph-7 :is(th, td):nth-child(7),
        & table.dg-ph-8 :is(th, td):nth-child(8),
        & table.dg-ph-9 :is(th, td):nth-child(9),
        & table.dg-ph-10 :is(th, td):nth-child(10),
        & table.dg-ph-11 :is(th, td):nth-child(11),
        & table.dg-ph-12 :is(th, td):nth-child(12),
        & table.dg-ph-13 :is(th, td):nth-child(13),
        & table.dg-ph-14 :is(th, td):nth-child(14) { display: none; }
        /* card rows: each row a card, each cell a labelled line (data-label) */
        & table.dg-cards {
            &, & tbody { display: block; }
            & thead { display: none; }
            & tbody tr { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.3rem 0.75rem; margin-block-end: 0.6rem; padding: 0.7rem 0.75rem; border: 1px solid var(--color-border); border-radius: var(--radius-lg); background: var(--color-panel); &:has(td[colspan]) { display: table-row; padding: 0; border: 0; background: none; } }
            & tbody td { display: block; flex: 1 1 100%; min-inline-size: 0; padding: 0; border: 0; text-align: start; white-space: normal; overflow-wrap: anywhere; &:first-child { font-weight: 600; } &:empty, &[data-card-hide] { display: none; } &[data-label] { display: flex; align-items: baseline; gap: 0.4rem; &::before { content: attr(data-label); flex: none; min-inline-size: 5.5rem; color: var(--dg-card-label-fg); font-size: var(--text-meta); letter-spacing: 0.04em; text-transform: uppercase; } } }
        }
    }
}

/* flex-wrap is load-bearing on a phone. A tab strip is not always a few short words: a strip with four tabs and three link
   buttons measured 633px inside a 375px page with nowrap, which does not clip, it takes the WHOLE page into horizontal scroll.
   Wrapping costs a second line only when there is no room. */

.tabs {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-1);
    border-bottom: 1px solid var(--color-border);
    margin-bottom: var(--space-4);
}

.tab {
    padding: var(--space-2) var(--space-4);
    background: transparent;
    border: none;
    border-bottom: 2px solid transparent;
    cursor: pointer;
    color: var(--color-muted);
    font-size: var(--text-read);
}

.tab:hover {
    color: inherit;
}

.tab.active {
    color: inherit;
    border-bottom-color: var(--color-accent);
}

.tab-close {
    margin-left: -0.5rem;
    padding: 0 0.35rem;
    background: transparent;
    border: none;
    cursor: pointer;
    color: var(--color-muted);
    font-size: var(--text-sm);
}

.tab-close:hover {
    color: inherit;
}

/* Tabs that slide instead of wrapping: one row, swipeable, scrollbar hidden. */
.tabs--scroll { flex-wrap: nowrap; overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x proximity; scrollbar-width: none; }
.tabs--scroll::-webkit-scrollbar { display: none; }
.tabs--scroll > * { flex: none; scroll-snap-align: start; white-space: nowrap; }

/* A tab that exists only at phone width. */
.tab--phone-only { display: none; }

@media (max-width: 640px) {
    .tab--phone-only { display: inline-block; }
    .tab--desktop-only { display: none; }
}

/* A tab that is a link (a page-level nav strip): same look, no underline. */
a.tab { display: inline-block; text-decoration: none; }

// Plainkit tabs behaviour: arrow-key roving focus, click-to-select for vanilla pages, scroll-into-view of the
// active tab, and a close event. Framework-free; no imports.
//
// Markup contract: <div class="tabs" role="tablist" data-pk-tabs> holding <button class="tab" role="tab"
// aria-selected tabindex> children; the selected one has .active. An optional .tab-close button follows the tab it closes.
//
// Options (initTabs(root, options), each also readable from a data- attribute on the tablist):
//   data-pk-tabs="toggle"        the module moves .active / aria-selected / tabindex on click. Omit when a
//                                 host framework owns the selected state (keyboard, scroll and close event still work).
//   scrollIntoView (default true) keep the active tab visible in a scrolling strip. data-pk-scroll="off" disables it.
//   data-pk-close="remove"       (with toggle) a close button also removes the tab and selects a neighbour.
//                                 Without it the module only fires the event and the page decides.
// Events: "pk-tab-close" (bubbles, cancelable) on the tablist, detail { tab, list }.

// Next index for an arrow/Home/End key over `count` tabs, or null when the key is not a tabs key.
export function nextTabIndex(current, count, key) {
    if (count === 0) return null;
    switch (key) {
        case 'ArrowRight': return (current + 1) % count;
        case 'ArrowLeft': return (current - 1 + count) % count;
        case 'Home': return 0;
        case 'End': return count - 1;
        default: return null;
    }
}

// New scrollLeft that brings a tab fully into view, leaving `margin` px around it; unchanged when it is already visible.
export function scrollLeftFor(tabLeft, tabWidth, viewWidth, current, margin = 8) {
    if (tabLeft - margin < current) return Math.max(0, tabLeft - margin);
    const right = tabLeft + tabWidth + margin;
    if (right > current + viewWidth) return right - viewWidth;
    return current;
}

// Which index to select after removing `removed` from `count` tabs, or -1 when none are left.
export function indexAfterClose(removed, count) {
    if (count <= 1) return -1;
    return Math.min(removed, count - 2);
}

const tabsOf = list => Array.from(list.querySelectorAll(':scope > .tab'));

function select(list, tab) {
    for (const t of tabsOf(list)) {
        const on = t === tab;
        t.classList.toggle('active', on);
        t.setAttribute('aria-selected', on ? 'true' : 'false');
        t.tabIndex = on ? 0 : -1;
    }
}

function reveal(list, tab, options) {
    if (options.scrollIntoView === false || list.getAttribute('data-pk-scroll') === 'off') return;
    list.scrollLeft = scrollLeftFor(tab.offsetLeft, tab.offsetWidth, list.clientWidth, list.scrollLeft);
}

function closeTargetOf(button) {
    let node = button.previousElementSibling;
    while (node && !node.classList.contains('tab')) node = node.previousElementSibling;
    return node;
}

export function initTabs(root = document, options = {}) {
    const doc = root.ownerDocument ?? root;
    root.querySelectorAll?.('[data-pk-tabs] > .tab.active').forEach(tab => reveal(tab.parentElement, tab, options));

    root.addEventListener('keydown', event => {
        const list = event.target.closest?.('[data-pk-tabs]');
        if (!list) return;
        const tabs = tabsOf(list);
        const index = tabs.indexOf(event.target);
        if (index === -1) return;
        const next = nextTabIndex(index, tabs.length, event.key);
        if (next === null) return;
        event.preventDefault();
        tabs[next].focus();
        tabs[next].click();
    });

    root.addEventListener('click', event => {
        const close = event.target.closest?.('.tab-close');
        if (close) {
            const list = close.parentElement;
            if (!list?.hasAttribute('data-pk-tabs')) return;
            const tab = closeTargetOf(close);
            const CustomEventCtor = (doc.defaultView ?? globalThis).CustomEvent;
            const signal = new CustomEventCtor('pk-tab-close', { bubbles: true, cancelable: true, detail: { tab, list } });
            list.dispatchEvent(signal);
            if (signal.defaultPrevented || list.getAttribute('data-pk-tabs') !== 'toggle' || list.getAttribute('data-pk-close') !== 'remove' || !tab) return;
            const tabs = tabsOf(list);
            const removed = tabs.indexOf(tab);
            const wasActive = tab.classList.contains('active');
            tab.remove();
            close.remove();
            const rest = tabsOf(list);
            const pick = indexAfterClose(removed, tabs.length);
            if (wasActive && pick >= 0) { select(list, rest[pick]); reveal(list, rest[pick], options); }
            return;
        }

        const tab = event.target.closest?.('.tab');
        const list = tab?.parentElement;
        if (!list?.hasAttribute('data-pk-tabs')) return;
        if (list.getAttribute('data-pk-tabs') === 'toggle') select(list, tab);
        reveal(list, tab, options);
    });
}

// Unit tests for the tabs component's behaviour, run against the fake DOM. Run: node --test sdk
import test from 'node:test';
import assert from 'node:assert/strict';
import { createDocument, el, FakeEvent } from '../../tests/fake-dom.mjs';
import { initTabs, scrollLeftFor, indexAfterClose } from './tabs.js';

const tabsFixture = (mode = 'toggle', extra = {}) => {
    const doc = createDocument();
    const t = n => el(doc, 'button.tab', { role: 'tab' });
    const a = t(); a.classList.add('active'); a.setAttribute('aria-selected', 'true');
    const b = t(); const c = t();
    const closeB = el(doc, 'button.tab-close');
    const list = el(doc, 'div.tabs', { 'data-pk-tabs': mode, ...extra }, a, b, closeB, c);
    doc.documentElement.append(list);
    return { doc, list, a, b, c, closeB };
};

test('tabs: click selects when the tablist toggles, and sets aria-selected and tabindex', () => {
    const { doc, a, b } = tabsFixture();
    initTabs(doc);
    b.click();
    assert.equal(b.classList.contains('active'), true);
    assert.equal(a.classList.contains('active'), false);
    assert.equal(b.getAttribute('aria-selected'), 'true');
    assert.equal(a.getAttribute('aria-selected'), 'false');
    assert.equal(b.tabIndex, 0);
});

test('tabs: a host-owned tablist (no toggle value) is not changed by a click', () => {
    const { doc, a, b } = tabsFixture('');
    initTabs(doc);
    b.click();
    assert.equal(a.classList.contains('active'), true);
    assert.equal(b.classList.contains('active'), false);
});

test('tabs: arrow keys move focus and select the next tab', () => {
    const { doc, a, b } = tabsFixture();
    initTabs(doc);
    a.dispatchEvent(new FakeEvent('keydown', { key: 'ArrowRight' }));
    assert.equal(doc.activeElement, b);
    assert.equal(b.classList.contains('active'), true);
});

test('tabs: the close button fires pk-tab-close with the tab it belongs to', () => {
    const { doc, list, b, closeB } = tabsFixture();
    initTabs(doc);
    let seen = null;
    list.addEventListener('pk-tab-close', e => { seen = e.detail.tab; e.preventDefault(); });
    closeB.click();
    assert.equal(seen, b);
    assert.equal(list.children.includes(b), true, 'a prevented event leaves the tab in place');
});

test('tabs: data-pk-close="remove" removes the tab and selects a neighbour when it was active', () => {
    const { doc, list, a, b, closeB } = tabsFixture('toggle', { 'data-pk-close': 'remove' });
    initTabs(doc);
    b.click();
    closeB.click();
    assert.equal(list.children.includes(b), false);
    assert.equal(list.children.includes(closeB), false);
    assert.equal(a.classList.contains('active') || list.children.some(c => c.classList.contains('active')), true);
});

test('tabs: the active tab is scrolled into view when selected in a scrolling strip', () => {
    const { doc, list, c } = tabsFixture();
    list.clientWidth = 200; c.offsetLeft = 500; c.offsetWidth = 100;
    initTabs(doc);
    c.click();
    assert.equal(list.scrollLeft, 500 + 100 + 8 - 200);
});

test('scrollLeftFor keeps a visible tab where it is and reveals hidden ones on either side', () => {
    assert.equal(scrollLeftFor(50, 80, 300, 0), 0);
    assert.equal(scrollLeftFor(400, 80, 300, 0), 188);
    assert.equal(scrollLeftFor(10, 80, 300, 200), 2);
});

test('indexAfterClose picks the same slot, then the last, then none', () => {
    assert.equal(indexAfterClose(1, 4), 1);
    assert.equal(indexAfterClose(3, 4), 2);
    assert.equal(indexAfterClose(0, 1), -1);
});

.toolbar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-2) var(--space-4); margin: var(--space-1) 0 var(--space-3) 0; }

.toolbar-lead { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--space-1) var(--space-3); min-width: 0; }

.toolbar-note { color: var(--color-muted); font-size: var(--text-md); }

.toolbar-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); margin-left: auto; }

.toolbar-actions .btn-mini { margin-right: 0; }

@media (max-width: 640px) {
.toolbar-lead { width: 100%; }
.toolbar-actions { width: 100%; margin-left: 0; }
}

.toolbar-title {
    color: var(--color-text);
}

.top-row {
    padding: 0 1.5rem;
    border-bottom: 1px solid var(--color-border);
    background: var(--color-panel);
    display: flex; align-items: center; gap: 0.5rem;
}

/* The top bar is the SITE header and is always present. It used to be hidden on
   desktop unless a page supplied content, which meant the app had no header at
   all on most screens and the page began flush against the window. */

.top-row {
    flex: none;
    height: var(--app-header-h);
}

/* Centred by taking the free space either side. margin:auto on a flex child
   centres against the row rather than against its siblings, so a long page
   title appearing after it does not drag the search off-centre. */

.app-header-search {
    flex: 1 1 auto;
    display: flex;
    justify-content: center;
    min-width: 0;
}

/* Hamburger button — hidden on desktop, shown in the top bar on small screens. */

.mobile-nav-toggle {
    display: none; flex: none; width: 34px; height: 34px; padding: 7px 6px;
    flex-direction: column; justify-content: space-between; cursor: pointer;
    background: transparent; border: 1px solid var(--color-border); border-radius: 7px;
}

.mobile-nav-toggle span { display: block; height: 2px; background: var(--color-text); border-radius: 2px; }

@media (max-width: 1024px) {
    /* content takes the full width */
    .top-row { display: flex; padding: 0 0.7rem; }
    .mobile-nav-toggle { display: flex; }
}

/* ── Site search (app header) ────────────────────────────────────────
   The input is centred in the header; results slide in over the content
   area once the query is long enough to mean something. */

.app-search { position: relative; width: min(34rem, 100%); }

.app-search-input {
    width: 100%;
    padding: 0.35rem 0.75rem;
    border: 1px solid var(--color-border);
    border-radius: 999px;
    background: var(--color-surface);
    color: inherit;
    font-size: var(--text-read);
}

.app-search-input:focus { outline: 2px solid var(--color-accent); outline-offset: 1px; }

@container (max-width: 60rem) {
    .app-search { width: 100%; }
}

/* ── Top bar: the page's back button and title live in the app header at every width; on a phone the search collapses to a button. ── */

.app-search-toggle,
.app-search-close { display: none; }

.app-header-title {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    flex: 0 1 auto;
    min-width: 0;
    max-width: 45%;
}

.topbar-title {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.topbar-back {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    min-width: var(--touch-target);
    min-height: var(--touch-target);
    color: inherit;
    text-decoration: none;
}

.topbar-back:hover { color: var(--color-accent); }

@media (max-width: 640px) {
    .app-header-title { flex: 1 1 auto; max-width: none; }
    .app-header-search { flex: none; }
    .app-search { width: auto; }
    .app-search-input { display: none; }
    .app-search-toggle,
    .app-search-close {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: var(--touch-target, 44px);
        min-height: var(--touch-target, 44px);
        background: transparent;
        border: 0;
        color: inherit;
        cursor: pointer;
    }
    .app-search.is-field {
        position: fixed;
        top: 0;
        left: 0;
        right: 0;
        height: var(--app-header-h);
        z-index: 1600;
        display: flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0 0.7rem;
        background: var(--color-panel);
    }
    .app-search.is-field .app-search-input { display: block; flex: 1 1 auto; width: auto; }
    .app-search.is-field .app-search-toggle { display: none; }
    .app-search:not(.is-field) .app-search-close { display: none; }
}

@media (max-width: 640px) {
    .mobile-nav-toggle { width: var(--touch-target); height: var(--touch-target); }
}

// Plainkit search field: on a phone the search collapses to an icon button; the button turns the bar into a
// full-width field and Escape or the close button puts it back. Framework-free; no imports.
//
// Markup contract (topbar.css): <div class="app-search" data-pk-search> holding button.app-search-toggle,
// input.app-search-input and button.app-search-close. Open state is the .is-field class on the wrapper.
// Options: data-pk-search-openclass (default "is-field") names the class; data-pk-search-focus="off" skips moving focus.

export const DEFAULT_OPEN_CLASS = 'is-field';

// Next open state for an event: "toggle" and "focus" open, "close" and Escape close, anything else leaves it.
export function nextSearchState(open, event) {
    switch (event) {
        case 'toggle':
        case 'focus': return true;
        case 'close':
        case 'Escape': return false;
        default: return open;
    }
}

function apply(box, open, options) {
    const cls = box.getAttribute('data-pk-search-openclass') ?? options.openClass ?? DEFAULT_OPEN_CLASS;
    const was = box.classList.contains(cls);
    box.classList.toggle(cls, open);
    const focusOn = box.getAttribute('data-pk-search-focus') !== 'off' && options.focus !== false;
    if (open && !was && focusOn) box.querySelector('.app-search-input')?.focus();
    if (!open && was && focusOn) box.querySelector('.app-search-toggle')?.focus();
    box.querySelector('.app-search-toggle')?.setAttribute('aria-expanded', open ? 'true' : 'false');
}

export function initSearchFields(root = document, options = {}) {
    root.addEventListener('click', event => {
        const box = event.target.closest?.('[data-pk-search]');
        if (!box) return;
        if (event.target.closest('.app-search-toggle')) apply(box, nextSearchState(false, 'toggle'), options);
        else if (event.target.closest('.app-search-close')) apply(box, nextSearchState(true, 'close'), options);
    });
    root.addEventListener('keydown', event => {
        const box = event.target.closest?.('[data-pk-search]');
        if (!box || event.key !== 'Escape') return;
        event.preventDefault();
        apply(box, nextSearchState(true, 'Escape'), options);
    });
}

