/* Typography helpers. Global classes on purpose: prose styles arbitrary content, and a shadow root cannot reach the descendants of slotted nodes.
   Every size is a token; reading text stays at or above --text-read and meta at or above --text-meta. */
.lead { font-size: var(--text-lg); line-height: 1.5; color: var(--color-muted); max-inline-size: 65ch; }

.small { font-size: var(--text-meta); }

