    { metric: 'contrastFail', reason: 'Text pairs measured against the panel: the muted and accent text on the light theme sit just under 4.5:1. Changing them restyles the whole app, so it needs an owner colour decision.' },
    { metric: 'touch-target', reason: 'Dense controls (mini buttons, tree rows, tab close, crumbs) are below 44px on a phone by design; the a11y layer raises the common ones. Reported per control by the scorecard run.' },
];

// Weight budgets, enforced by tests/budgets.test.mjs. target is the aim; limit is what the test allows today and only ever comes down.
// Reference: Bootstrap 5 ships about 25 KB gzip CSS and 16 KB gzip JS. The SDK's CSS covers the whole app (data grid, code explorer,
// workspace, shell) and is not yet at target; every module is loaded only where used, and first paint needs no JS at all.
// What the static score measures: the new API only. The page-level sheets, every element's css, and the scripts (shared modules and element behaviours).
export const PRIMARY_CSS = ['tokens/tokens.css', 'base/base.css', 'components/utilities/utilities.css', 'components/spacing/spacing.css', 'base/a11y.css'];

export const BUDGETS = {
    // The element pipeline and the class-based compat layer are budgeted separately. Limits only ever come down.
    pageCssGzKb: { target: 8, limit: 10, reference: 25, note: 'dist/plainkit.css: tokens, base, utilities, spacing and a11y for the light DOM (Bootstrap 5 CSS is about 25 KB gzip)' },
    compatCssGzKb: { limit: 42, note: 'dist/plainkit-compat.css: the class-based components kept for the Blazor app until its wrappers use the pk-* elements. It holds the groups that are not converted yet (29.3 KB was the whole layer before the forms, data display and overlay groups arrived); the limit drops as each group becomes elements, and nothing is added.' },
    elementGzKb: { target: 2, limit: 4, note: 'one dist/elements/<name>.js: template, css and behaviour together' },
    baseRuntimeGzKb: { target: 2, limit: 2.5, note: 'js/element.js + js/element-core.js (comments stripped)' },
    jsModuleGzKb: { target: 3, limit: 6 },
    baseJsGzKb: { target: 0, limit: 10, note: 'the modules a plain page imports through plainkit.js: overlay, tabs, search-field, workspace, nav, theme, colour' },
};

// Text policy, two tiers (px at the 14px root). Reading text (body, cells, labels, inputs, buttons, nav items, help) is at least
// 14px. Secondary text (the selectors below) is at least 12px. Anything under 12px, or reading text under 14px, is a defect.
// Mini buttons are 12px and stay a desktop-density control: above 640px only.
export const TEXT_TIERS = {
    readingPx: 14,
    metaPx: 12,
    demoSelectors: '.gx-effect *, .gx-demo *',
    metaSelectors: '.infotip__icon, .gal-add-hint, .gx-code, .gx-code *, .tab-close, .csr-text, .csr-text *, .gx-effect *, .gx-demo *, .shell-footer, .shell-footer *, .gx-icon, .gx-icon *, .gx-box *, .gx-z *, .cv-scroll, .cv-scroll *, .chip, .badge, .snav-badge, .snav-group-title, .cv-no, .csr-no, .co-kind, .co-line, .ft-lines, .ft-count, .u-text-xs, .u-text-sm, .field-help, .field-error, .ff-hint, .page-crumbs, .page-crumbs *, .toolbar-note, .stat-card-label, .stat-card-subtext, .infotip__panel, .infotip__panel *, th, .gx-group-label, .gx-param-type, .section-header-note, .cv-meta, .cv-meta *, .cv-notice, .gal-badge, .combo-empty, .pd-reset, .btn-mini, kbd, time, .tag-pill, .tag-pill *, .stepper li::before',
};
// Phone touch targets that are exempt, each with its reason (the scorecard lists these; a target not matching one is a defect).
export const TARGET_EXCEPTIONS = [
    { selector: 'input[type="range"]', reason: 'Native slider: the browser draws its own thumb and hit area; the row it sits in is tall enough.' },
    { selector: 'input[type="file"]', reason: 'Native file picker button; its label row is the tap target.' },
    { selector: '.tag-pill-x', reason: 'Remove control inside a tag pill; the pill and the text field are the targets, and a 44px cross would double the pill height.' },
    { selector: '.cnb-folder', reason: 'A breadcrumb-style text button in a path trail, like the crumb links.' },
];

{
  "note": "Counts per severity may only go down. Refresh with node tools/security.mjs --write after a fix.",
  "counts": {
    "critical": 0,
    "high": 0,
    "medium": 0,
    "low": 6
  }
}

// Headless subset of the scorecard: node core/site/scorecard/static-audit.mjs
// Measures what needs no browser (stylesheet and script size, literal colours and sizes, text-pair contrast), scores it with the
// same definitions as the scorecard page, and prints the result. Exits 1 when the static score is below --min (default 0).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { staticMetrics } from '../../js/audit.js';
import { scoreAll } from '../../js/scoring.js';
import { SCORING, TEXT_PAIRS, EXCEPTIONS, PRIMARY_CSS } from './scoring.data.js';

const sdkRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

// The files a module pulls in through static import/export-from, transitively (relative specifiers only).
function baseClosure(root, entry) {
    const seen = new Set(); const queue = [entry];
    while (queue.length) {
        const f = queue.pop(); if (seen.has(f) || !fs.existsSync(path.join(root, f))) continue; seen.add(f);
        const src = fs.readFileSync(path.join(root, f), 'utf8');
        for (const m of src.matchAll(/(?:import|export)\s[^'"]*?from\s+['"](\.[^'"]+)['"]|import\s+['"](\.[^'"]+)['"]/g))
            queue.push(path.posix.normalize(path.posix.join(path.posix.dirname(f), m[1] ?? m[2])));
    }
    return [...seen];
}

export function readPlainkit(root = sdkRoot) {
    const walk = d => (fs.existsSync(d) ? fs.readdirSync(d, { withFileTypes: true }).flatMap(e => (e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)])) : []);
    const rel = f => path.relative(root, f).split(path.sep).join('/');
    const text = f => fs.readFileSync(f, 'utf8').replace(/\r\n/g, '\n');
    const elementFiles = walk(path.join(root, 'elements')).map(rel);
    const names = [...PRIMARY_CSS, ...elementFiles.filter(f => f.endsWith('.css') && !f.endsWith('elements.css'))];
    const cssFiles = Object.fromEntries(names.map(n => [n, text(path.join(root, n))]));
    // Script weight is what EVERY page loads: the closure of js/plainkit.js. Elements and their behaviour modules load on demand and
    // are held to per-element budgets by tests/budgets.test.mjs, so counting them here would punish a bigger component set.
    const jsNames = baseClosure(root, 'js/plainkit.js');
    const jsFiles = Object.fromEntries(jsNames.map(f => [f, text(path.join(root, f))]));
    return { cssFiles, jsFiles, tokensCss: cssFiles['tokens/tokens.css'] };
}

export function runStaticAudit(root = sdkRoot) {
    const metrics = staticMetrics({ ...readPlainkit(root), pairs: TEXT_PAIRS });
    const measured = { cssKb: metrics.cssKb, jsKb: metrics.jsKb, literalColours: metrics.literalColours, literalSizes: metrics.literalSizes, contrastFail: metrics.contrastFail };
    return { metrics, measured, scores: scoreAll(SCORING, measured) };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
    const { metrics, scores } = runStaticAudit();
    console.log(`CSS ${metrics.cssKb} KB, JS ${metrics.jsKb} KB, literal colours ${metrics.literalColours}, literal size share ${metrics.literalSizes}, failing text pairs ${metrics.contrastFail}`);
    for (const [key, c] of Object.entries(scores.categories)) console.log(`${c.label.padEnd(14)} ${c.score ?? 'n/a'}`);
    console.log(`Static overall ${scores.overall}`);
    if (process.argv.includes('--write')) {
        const scoresOnly = Object.fromEntries(Object.entries(scores.categories).map(([k, c]) => [k, c.score]));
        fs.writeFileSync(path.join(sdkRoot, 'site', 'scorecard', 'baseline.json'), JSON.stringify({ note: 'Static scores only go up: the test fails when one drops. Refresh with node site/scorecard/static-audit.mjs --write after an improvement.', overall: scores.overall, categories: scoresOnly }, null, 2) + '\n');
        fs.writeFileSync(path.join(sdkRoot, 'site', 'scorecard', 'report.json'), JSON.stringify({ generated: new Date().toISOString(), metrics: { ...metrics, perFile: undefined }, perFile: metrics.perFile.map(f => ({ name: f.name, bytes: f.bytes, rules: f.rules, literalColours: f.literalColours, literalSizes: f.literalSizes })), scores: { overall: scores.overall, categories: scoresOnly }, exceptions: EXCEPTIONS }, null, 2) + '\n');
    }
    const min = Number(process.argv[process.argv.indexOf('--min') + 1]) || 0;
    if (scores.overall !== null && scores.overall < min) process.exit(1);
}

// Size sweep: every gallery view, every template and every control sample at 320, 375, 640, 1024, 1280 and 1920px in both themes,
// measuring horizontal overflow, controls under 44px on a phone, nested scrollers, text under 14px and the number of h1 elements.
// Runs in the scorecard page (needs a visible tab: it uses real layout). Results can be POSTed to tools/serve.mjs --write-reports,
// which stores them in scorecard/sweep-report.json. Framework-free; ES module.

import { CONTROLS, KINDS, LAYOUTS, PATTERNS, TEMPLATES, ELEMENTS } from '../gallery/gallery.data.js';
import { sampleDoc } from '../gallery/frame.js';
import { TEXT_TIERS, TARGET_EXCEPTIONS } from './scoring.data.js';

// Results collected so far, so an interrupted run loses nothing.
export const partial = [];

export const WIDTHS = [320, 375, 640, 1024, 1280, 1920];
export const THEMES = ['dark', 'light'];
const FOUNDATIONS = ['colours', 'typography', 'spacing', 'radii-shadows', 'breakpoints', 'utilities', 'icons', 'tokens'];
const TEMPLATE_FILES = TEMPLATES.map(x => x.file.replace('samples/templates/', ''));
const slug = s => s.replace(/\W+/g, '-').replace(/^-|-$/g, '').toLowerCase();

export function routes() {
    const kinds = KINDS.filter(k => k !== 'Page templates');
    return [
        '#/foundations', ...FOUNDATIONS.map(f => `#/foundations/${f}`), '#/controls', ...kinds.map(k => `#/controls/${slug(k)}`),
        ...CONTROLS.filter(c => c.kind !== 'Page templates').map(c => `#/controls/${slug(c.kind)}/${c.id}`),
        '#/overview', '#/samples', '#/samples/templates', ...TEMPLATES.map(x => `#/samples/templates/${x.id}`), '#/samples/patterns', ...PATTERNS.map(p => `#/samples/patterns/${p.id}`),
        '#/samples/layouts', '#/samples/layouts/shell', '#/samples/layouts/responsive', ...LAYOUTS.map(l => `#/samples/layouts/${l.id}`), '#/samples/blocks', '#/elements', ...ELEMENTS.map(m => `#/elements/${m.tag}`),
    ];
}

const INTERACTIVE = 'a[href], button, input:not([type="hidden"]):not([type="checkbox"]):not([type="radio"]), select, textarea, summary, [role="tab"]';

// Measures one document at a viewport width. `phone` turns on the touch-target check. Pure over the DOM it is given.
export function measure(doc, width, { checkH1 = true } = {}) {
    const win = doc.defaultView; const de = doc.documentElement; const out = { overflow: 0, smallTargets: 0, nestedScrollers: 0, smallText: 0, metaTooSmall: 0, readingSmall: 0, h1: null };
    out.overflow = Math.max(0, de.scrollWidth - de.clientWidth);
    if (width <= 640) {
        for (const el of doc.querySelectorAll(INTERACTIVE)) {
            if (el.closest('[hidden]') || el.disabled) continue;
            const r = el.getBoundingClientRect(); if (r.width === 0 || r.height === 0) continue;
            if (r.height < 43.5 && !(el.tagName === 'A' && win.getComputedStyle(el).display === 'inline') && !el.closest('.ft, .co, .csr, .cv, .page-crumbs, .tab-close') && !TARGET_EXCEPTIONS.some(x => el.matches(x.selector))) out.smallTargets++;
        }
    }
    const scrolls = el => { const s = win.getComputedStyle(el); return /(auto|scroll)/.test(s.overflowX + s.overflowY) && (el.scrollHeight > el.clientHeight + 1 || el.scrollWidth > el.clientWidth + 1); };
    for (const el of doc.querySelectorAll('*')) {
        if (!scrolls(el) || el === doc.body || el === de) continue;
        for (let p = el.parentElement; p && p !== doc.body; p = p.parentElement) if (scrolls(p)) { out.nestedScrollers++; break; }
    }
    const walker = doc.createTreeWalker(doc.body, 4);
    for (let n = walker.nextNode(); n; n = walker.nextNode()) {
        if (!n.textContent.trim()) continue;
        const el = n.parentElement; if (!el || el.closest('[hidden], script, style, .u-sr-only') || el.getBoundingClientRect().width === 0) continue;
        if (el.closest(TEXT_TIERS.demoSelectors)) continue;
        const px = parseFloat(win.getComputedStyle(el).fontSize);
        if (px < TEXT_TIERS.metaPx - 0.5) out.metaTooSmall++;
        else if (px < TEXT_TIERS.readingPx - 0.5 && !el.closest(TEXT_TIERS.metaSelectors)) out.readingSmall++;
    }
    out.smallText = out.metaTooSmall + out.readingSmall;
    if (checkH1) out.h1 = doc.querySelectorAll('h1').length;
    return out;
}

function frame(src, width, doc) {
    return new Promise(resolve => {
        const f = document.createElement('iframe');
        f.style.cssText = `position:fixed;left:-20000px;top:0;width:${width}px;height:900px;border:0`;
        if (doc) f.srcdoc = doc; else f.src = src;
        document.body.append(f);
        // Settled when the document has content and its node count has stopped changing, or after 6s.
        const started = Date.now(); let last = -1; let stable = 0;
        const timer = setInterval(() => {
            const d = f.contentDocument; const n = d?.body ? d.body.querySelectorAll('*').length : 0;
            stable = n > 3 && n === last ? stable + 1 : 0; last = n;
            // Styles must be applied before anything is measured: every stylesheet link loaded (a half-styled frame reads as small targets and text).
            const styled = !!d && [...d.querySelectorAll('link[rel=stylesheet]')].every(l => l.sheet);
            const ready = styled && (src ? !!d?.querySelector('h1') : true);
            if ((ready && stable >= (src ? 5 : 3)) || Date.now() - started > 8000) { clearInterval(timer); resolve(f); }
        }, 120);
    });
}

async function pool(jobs, size, onDone) {
    let next = 0; let done = 0;
    await Promise.all(Array.from({ length: size }, async () => { while (next < jobs.length) { await jobs[next++](); onDone?.(++done, jobs.length); } }));
}

// kinds: any of 'views', 'templates', 'samples'. Returns { checked, failures: [{ item, width, theme, ...metrics }], results }.
export async function sweep({ kinds = ['views', 'templates', 'samples'], widths = WIDTHS, themes = THEMES, progress, size = 6 } = {}) {
    const results = partial; results.length = 0; const jobs = [];
    const add = (item, run) => { for (const theme of themes) for (const width of widths) jobs.push(async () => { try { const m = await run(width, theme); results.push({ item, width, theme, ...m }); } catch (e) { results.push({ item, width, theme, error: String(e), overflow: 0, smallTargets: 0, nestedScrollers: 0, smallText: 0, h1: null }); } }); };
    if (kinds.includes('views')) for (const r of routes()) add(`gallery ${r}`, async (w, theme) => { const f = await frame(new URL(`../gallery/index.html?theme=${theme}${r}`, import.meta.url).href, w); try { return measure(f.contentDocument, w); } finally { f.remove(); } });
    if (kinds.includes('templates')) for (const t of TEMPLATE_FILES) for (const nav of ['side', 'top']) add(`template ${t} (${nav} nav)`, async (w, theme) => { const f = await frame(new URL(`../../samples/templates/${t}?nav=${nav}&theme=${theme}`, import.meta.url).href, w); try { return measure(f.contentDocument, w); } finally { f.remove(); } });
    if (kinds.includes('samples')) for (const c of CONTROLS) c.samples.forEach((s, i) => add(`sample ${c.id}#${i + 1}`, async (w, theme) => { const f = await frame(null, w, sampleDoc(s.html, { theme, script: s.script })); try { return measure(f.contentDocument, w, { checkH1: false }); } finally { f.remove(); } }));
    await pool(jobs, size, progress);
    const bad = r => r.error || r.overflow > 0 || r.smallTargets > 0 || r.nestedScrollers > 0 || r.smallText > 0 || (r.h1 !== null && r.h1 !== 1 && !r.item.startsWith('template auth') && !r.item.startsWith('gallery #/foundations/icons'));
    return { checked: results.length, failures: results.filter(bad), results };
}

export function summarise(report) {
    const by = { overflow: 0, smallTargets: 0, nestedScrollers: 0, metaTooSmall: 0, readingSmall: 0, h1: 0 };
    for (const r of report.failures) { if (r.overflow > 0) by.overflow++; if (r.smallTargets > 0) by.smallTargets++; if (r.nestedScrollers > 0) by.nestedScrollers++; if (r.metaTooSmall > 0) by.metaTooSmall++; if (r.readingSmall > 0) by.readingSmall++; if (r.h1 !== null && r.h1 !== 1) by.h1++; }
    return { checked: report.checked, failing: report.failures.length, by, widths: WIDTHS, themes: THEMES };
}

export async function postReport(report, { part, final } = {}, url = '/__report') {
    const q = new URLSearchParams({ ...(part ? { part } : {}), ...(final ? { final: '1' } : {}) }).toString();
    const res = await fetch(url + (q ? '?' + q : ''), { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ checked: report.checked, failures: report.failures, widths: WIDTHS, themes: THEMES }) });
    return res.status;
}

// The settings page: theme, gallery text size and sample width. Values live in localStorage through the shared settings helper.
import { mountShell, readSetting, writeSetting } from '../shell.js';
import { setTheme, currentTheme } from '../../js/theme.js';

mountShell({ page: 'settings', title: null });
const root = document.documentElement;
const $ = s => document.querySelector(s);
const paint = () => document.querySelectorAll('pk-button[value]').forEach(b => b.toggleAttribute('pressed', b.getAttribute('value') === currentTheme(root)));

paint();
// Attributes, not properties: the elements may not be upgraded yet, and a property set now would shadow their accessor.
$('#set-scale').setAttribute('value', readSetting('pk-gallery-scale') ?? '1');
$('#set-width').setAttribute('value', readSetting('pk-gallery-width') === 'phone' ? 'phone' : 'desktop');
$('pk-button-group').addEventListener('pk-toggle', e => {
    const name = e.target.closest('pk-button')?.getAttribute('value');
    if (!name || name === currentTheme(root)) return;
    setTheme(root, name); writeSetting('pk-site-theme', name); paint();
    document.dispatchEvent(new CustomEvent('site-theme', { detail: name }));
    const t = $('#site-theme'); if (t) t.textContent = name === 'dark' ? 'Light theme' : 'Dark theme';
});
document.addEventListener('site-theme', paint);
$('#set-scale').addEventListener('pk-value-change', e => writeSetting('pk-gallery-scale', e.detail.value));
$('#set-width').addEventListener('pk-value-change', e => writeSetting('pk-gallery-width', e.detail.value));

// Templates and Spacing are sections of the Gallery's own tree (#/samples/templates, #/foundations/spacing), not top-level pages.
// The SDK site shell: ONE primary navigation, the top navbar (pk-navbar: brand, page links, search that collapses on a phone, settings
// menu, hamburger). Each page owns its own content tree below it (the gallery's side nav is that tree). Built from the SDK's own
// elements, so the site is the showcase. Framework-free; ES module.

import { initPlainkit } from '../js/plainkit.js';
import { toggleTheme, setTheme, currentTheme } from '../js/theme.js';
import { readSetting as read, writeSetting as write } from './gallery/settings.js';

const PK_ROOT = new URL('../', import.meta.url).href;
export const PAGES = [
    { key: 'gallery', title: 'Gallery', href: '../gallery/index.html' },
    { key: 'files', title: 'Files', href: '../files/index.html' },
    { key: 'scorecard', title: 'Scorecard', href: '../scorecard/index.html' },
    { key: 'theme', title: 'Theme editor', href: '../theme/index.html' },
    { key: 'guides', title: 'Guides', href: '../guides/index.html' },
    { key: 'devtools', title: 'Dev tools', href: '../devtools/index.html' },
];

const THEME_KEY = 'pk-site-theme';

function h(tag, props = {}, ...children) {
    const el = document.createElement(tag);
    for (const [k, v] of Object.entries(props)) if (v !== undefined && v !== null && v !== false) el.setAttribute(k, v === true ? '' : v);
    el.append(...children);
    return el;
}

// The search field that collapses to a button on a phone. No element covers this yet, so it keeps the old app-search classes (wired by
// initPlainkit); everything around it is elements.
function searchField(placeholder) {
    return h('div', { class: 'app-search', 'data-pk-search': true },
        h('button', { type: 'button', class: 'app-search-toggle', 'aria-label': 'Search', 'aria-expanded': 'false' }, h('pk-icon', { name: 'search' })),
        h('input', { class: 'app-search-input', type: 'search', 'aria-label': placeholder, placeholder }),
        h('button', { type: 'button', class: 'app-search-close', 'aria-label': 'Close search' }, h('pk-icon', { name: 'x' })));
}

// The theme switch lives in the settings (profile) menu at the end of the bar, next to a link to the Settings page.
// options: { page, title, search: { placeholder } | null }. Dispatches "site-search" (detail: string) and "site-theme" (detail: name) on document.
export function mountShell({ page, title, search = null }) {
    const root = document.documentElement;
    setTheme(root, new URLSearchParams(location.search).get('theme') ?? read(THEME_KEY) ?? 'dark');
    document.body.classList.add('site');
    const themeItem = h('pk-menu-item', { id: 'site-theme' }, currentTheme(root) === 'dark' ? 'Light theme' : 'Dark theme');
    const header = h('pk-navbar', { label: 'Site' },
        h('a', { slot: 'brand', href: `${PK_ROOT}index.html` }, 'Plainkit'),
        ...PAGES.map(p => h('a', { href: p.href, 'aria-current': p.key === page ? 'page' : false }, p.title)),
        h('div', { slot: 'actions', class: 'site-actions' },
            ...(search ? [searchField(search.placeholder)] : []),
            h('pk-dropdown', { placement: 'bottom-end' },
                h('pk-button', { slot: 'trigger', variant: 'ghost', icon: true, label: 'Settings menu' }, h('pk-icon', { name: 'settings' })),
                themeItem,
                h('pk-menu-item', { href: '../settings/index.html', 'aria-current': page === 'settings' ? 'page' : false }, 'Settings'))));
    document.body.prepend(header);
    if (title) { const h1 = h('h1', { class: 'u-sr-only' }, title); header.after(h1); }
    themeItem.addEventListener('pk-select', () => {
        write(THEME_KEY, toggleTheme(root));
        themeItem.textContent = currentTheme(root) === 'dark' ? 'Light theme' : 'Dark theme';
        document.dispatchEvent(new CustomEvent('site-theme', { detail: currentTheme(root) }));
    });
    header.querySelector('.app-search-input')?.addEventListener('input', e => document.dispatchEvent(new CustomEvent('site-search', { detail: e.target.value })));
    initPlainkit(document);
    return { root };
}

export { read as readSetting, write as writeSetting };

/* SDK site chrome: the layout the standalone pages (gallery, theme, files, guides, scorecard) share.
   Everything reads SDK tokens; nothing here restyles an SDK control. */

.site { display: flex; flex-direction: column; height: 100vh; height: 100dvh; overflow: hidden; }

.site-body { flex: 1; min-height: 0; display: flex; flex-direction: column; }

.site-scroll { flex: 1; min-height: 0; overflow-y: auto; padding: var(--space-4); }

.site-scroll > * { max-width: 72rem; margin-inline: auto; }

.site-actions { display: flex; align-items: center; gap: var(--space-2); flex: none; }

.gx-notice-file { margin: var(--space-4); }

/* Top bar: a pk-navbar. Brand, search, settings menu and hamburger stay on ONE row at tablet and phone widths (the navbar's parts are reordered
   here), and the page links fold into a panel that overlays the content instead of pushing it down. The theme switch sits in the settings menu. */
.site > pk-navbar { position: relative; z-index: var(--z-sticky); }

/* Links in the light DOM answer to the page's link rules before the navbar's own, so the brand and page links are settled here. */
.site pk-navbar > a { color: inherit; text-decoration: none; }

.site pk-navbar > a[aria-current="page"] { color: var(--color-link); }

.site pk-navbar .app-search-input { width: 14rem; }

@media (max-width: 1024px) {
    .site pk-navbar::part(nav) { position: relative; flex-wrap: nowrap; gap: var(--space-1); padding-inline: var(--space-3); }

    .site pk-navbar::part(actions) { order: 2; margin-inline-start: auto; gap: var(--space-1); }

    .site pk-navbar::part(toggle) { order: 3; margin-inline-start: 0; }

