// The SDK theme editor page: a thin host on modules/theme-editor. The module lists every token, edits this page live, grades the text
// pairs and exports or imports the override block; this page adds the site shell, the SDK scorecard's text pairs, the storage key the
// page has always used, and the bridge that keeps the site's saved theme in step with the editor's Dark/Light switch.

import { mountShell, writeSetting } from '../shell.js';
import { mountThemeEditor } from '../../modules/theme-editor/theme-editor.js';
import { TEXT_PAIRS } from '../scorecard/scoring.data.js';

async function main() {
    mountShell({ page: 'theme', title: 'Theme editor' });
    const host = document.getElementById('te-host');
    await mountThemeEditor(host, { pairs: TEXT_PAIRS, storageKey: 'pk-theme-overrides' });
    document.getElementById('boot-notice')?.remove();
    new MutationObserver(() => writeSetting('pk-site-theme', document.documentElement.getAttribute('data-theme'))).observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });
}

main().catch(err => {
    const n = document.createElement('pk-alert');
    n.setAttribute('kind', 'danger');
    n.className = 'gx-notice-file';
    n.textContent = `The theme editor could not start: ${err.message}. Serve the Plainkit folder with a static server.`;
    document.body.append(n);
});

// site/scorecard/api.current.json is generated by the build (the scorecard's API section diffs it against the baseline): it must match the sources.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from '../tools/build.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

test('api.current.json is what the build produces from the sources (run node tools/build.mjs when it fails)', () => {
    const { out } = build({ write: false });
    const built = out.get('site/scorecard/api.current.json');
    assert.ok(built, 'the build does not write api.current.json');
    const disk = fs.readFileSync(path.join(root, 'site', 'scorecard', 'api.current.json'), 'utf8').replace(/\r\n/g, '\n');
    assert.equal(disk, built.replace(/\r\n/g, '\n'));
});

// Run with: node --test sdk/tests   (Node 20+, no dependencies). Covers the pure decision functions;
// DOM behaviour (focus hold, Escape) is exercised in the browser through index.html.
import test from 'node:test';
import assert from 'node:assert/strict';
import { tabTarget } from '../components/modal/modal.js';
import { nextTabIndex } from '../components/tabs/tabs.js';

test('tabTarget wraps from the last focusable to the first', () => {
    assert.equal(tabTarget(2, 3, false), 0);
});

test('tabTarget wraps from the first focusable to the last on Shift+Tab', () => {
    assert.equal(tabTarget(0, 3, true), 2);
});

test('tabTarget lets the browser move focus inside the list', () => {
    assert.equal(tabTarget(1, 3, false), null);
    assert.equal(tabTarget(1, 3, true), null);
});

test('tabTarget pulls focus back in when it is outside', () => {
    assert.equal(tabTarget(-1, 3, false), 0);
    assert.equal(tabTarget(-1, 3, true), 2);
});

test('tabTarget with nothing focusable targets the container', () => {
    assert.equal(tabTarget(-1, 0, false), -1);
});

test('nextTabIndex moves with the arrow keys and wraps', () => {
    assert.equal(nextTabIndex(0, 3, 'ArrowRight'), 1);
    assert.equal(nextTabIndex(2, 3, 'ArrowRight'), 0);
    assert.equal(nextTabIndex(0, 3, 'ArrowLeft'), 2);
});

test('nextTabIndex handles Home and End', () => {
    assert.equal(nextTabIndex(1, 4, 'Home'), 0);
    assert.equal(nextTabIndex(1, 4, 'End'), 3);
});

test('nextTabIndex ignores other keys and empty lists', () => {
    assert.equal(nextTabIndex(0, 3, 'a'), null);
    assert.equal(nextTabIndex(0, 0, 'ArrowRight'), null);
});

