        t.eq(m.style.getPropertyValue('--_r'), '4 / 3'); t.eq(m.part('box').getAttribute('role'), 'button');
        let open = null; m.addEventListener('pk-open', e => { open = e.detail; }); m.part('box').click(); t.eq(open.alt, 'cover'); t.eq(open.caption, 'C');
