        t.ok(seg.hasAttribute('variant')); t.eq(seg.value, '', 'nothing chosen yet'); seg.part('group').querySelectorAll('input')[1].click(); await t.settle(); t.eq(seg.value, 'w');
        t.ok(!g.hasAttribute('invalid'));
