/* Layout for the in-browser element test page only; not part of the SDK. */
.tb-results { padding-left: var(--space-6); }
.tb-results li { margin: var(--space-1) 0; }
.tb-pass::marker { color: var(--color-success, var(--color-accent)); }
.tb-fail { color: var(--color-error, var(--color-text)); }
.tb-stage { position: absolute; left: -10000px; top: 0; width: 900px; }

// In-browser test runner for the SDK's custom elements. Open /tests/browser/ in a visible tab. With node tools/serve.mjs --write-reports it
// also posts an attested report (tests/browser/report.json): the results plus a SHA-256 of every element source it covered, so a guard
// test can fail when a component changed after its last run without needing a browser in CI.
import { loadElements } from '../../js/loader.js';
import { cases } from './cases.js';

const stageEl = document.getElementById('stage');
const registryUrl = new URL('../../elements/registry.js', import.meta.url).href;

class Failure extends Error {}
const fmt = v => (typeof v === 'string' ? JSON.stringify(v) : String(v));

const t = {
    ok(v, msg = 'expected a truthy value') { if (!v) throw new Failure(msg); },
    eq(a, b, msg = '') { if (a !== b) throw new Failure(`${msg ? msg + ': ' : ''}expected ${fmt(b)}, got ${fmt(a)}`); },
    stage(html) { stageEl.replaceChildren(); const d = document.createElement('div'); d.innerHTML = html; stageEl.append(d); return d; },
    async load(root) { await loadElements(root, { registry: registryUrl }); const tags = [...root.querySelectorAll('*')].map(e => e.localName).filter(n => n.startsWith('pk-')); await Promise.all([...new Set(tags)].map(n => customElements.whenDefined(n))); await t.settle(); },
    async mount(html) { const host = t.stage(html); await t.load(host); return host.firstElementChild; },
    // Two message-channel hops: unlike requestAnimationFrame and timers, they are not throttled in a background tab.
    settle() { const hop = () => new Promise(r => { const c = new MessageChannel(); c.port1.onmessage = () => r(); c.port2.postMessage(0); }); return hop().then(hop); },
    key(el, key) { el.dispatchEvent(new KeyboardEvent('keydown', { key, bubbles: true, composed: true, cancelable: true })); },
    tabsHtml(activation = 'auto') {
        return `<pk-tabs activation="${activation}"><pk-tab value="a">A</pk-tab><pk-tab value="b">B</pk-tab><pk-tab value="c" disabled>C</pk-tab><pk-tab-panel value="a">Panel A</pk-tab-panel><pk-tab-panel value="b">Panel B</pk-tab-panel></pk-tabs>`;
    },
};

// Every source the tests cover, hashed the way tests/elements-attest.test.mjs hashes them on disk (LF-normalised SHA-256, hex).
async function sha(text) {
    const bytes = new TextEncoder().encode(text.replace(/\r\n/g, '\n'));
    return [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(b => b.toString(16).padStart(2, '0')).join('');
}

async function sources() {
    const registry = (await import(registryUrl)).default;
    const names = Object.keys(registry).map(tag => tag.slice(3));
    const files = ['js/element.js', 'js/element-core.js', 'js/loader.js', 'tests/browser/cases.js', 'tests/browser/cases-overlays.js', 'tests/browser/cases-data-display.js', 'tests/browser/cases-forms.js', 'tests/browser/cases-tools.js', 'tests/browser/cases-headers.js', 'tests/browser/cases-layout.js', 'tests/browser/cases-icon-time.js', 'tests/browser/cases-workspace.js', 'tests/browser/runner.js'];
    for (const n of names) for (const ext of ['html', 'css', 'meta.json', 'js']) files.push(`elements/${n}/${n}.${ext}`);
    const out = {};
    for (const f of files.sort()) { const res = await fetch(new URL(`../../${f}`, import.meta.url)); if (res.ok) out[f] = await sha(await res.text()); }
    return out;
}

const list = document.getElementById('results');
const results = [];
for (const [name, fn] of cases) {
    const started = performance.now();
    const li = document.createElement('li');
    try { await fn(t); li.className = 'tb-pass'; li.textContent = name; results.push({ name, ok: true, ms: Math.round(performance.now() - started) }); }
    catch (e) { li.className = 'tb-fail'; li.textContent = `${name}: ${e.message}`; results.push({ name, ok: false, ms: Math.round(performance.now() - started), error: String(e.message ?? e) }); }
    list.append(li);
}
stageEl.replaceChildren();

const passed = results.filter(r => r.ok).length; const failed = results.length - passed;
const summary = document.getElementById('summary');
summary.textContent = failed ? `${failed} of ${results.length} failed` : `All ${results.length} passed`;
document.title = `${failed ? 'FAIL' : 'PASS'} - SDK element tests`;
document.documentElement.dataset.done = failed ? 'fail' : 'pass';

const report = { ran: new Date().toISOString(), browser: navigator.userAgent, passed, failed, results, sources: await sources() };
window.__report = report;
try {
    const res = await fetch('/__report?kind=browser', { method: 'POST', body: JSON.stringify(report) });
    if (res.status === 204) summary.textContent += ' (report saved)';
} catch { /* not served with --write-reports: the page still shows the results */ }

// Weight budgets and the score ratchet. Budgets live in scorecard/scoring.data.js; limits only ever come down.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';
import { BUDGETS } from '../site/scorecard/scoring.data.js';
import { runStaticAudit } from '../site/scorecard/static-audit.mjs';
import { build } from '../tools/build.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = p => fs.readFileSync(path.join(root, p), 'utf8').replace(/\r\n/g, '\n');
const gzKb = text => zlib.gzipSync(Buffer.from(text)).length / 1024;

test('the page-level stylesheet, the compat layer and every element stay inside their own gzip budgets', () => {
    const { out } = build({ write: false });
    const gz = f => zlib.gzipSync(Buffer.from(out.get(f))).length / 1024;
    assert.ok(gz('dist/plainkit.css') < BUDGETS.pageCssGzKb.limit, `dist/plainkit.css is ${gz('dist/plainkit.css').toFixed(1)} KB gzip, limit ${BUDGETS.pageCssGzKb.limit} (target ${BUDGETS.pageCssGzKb.target}, Bootstrap 5 about ${BUDGETS.pageCssGzKb.reference})`);
    assert.ok(gz('dist/plainkit-compat.css') <= BUDGETS.compatCssGzKb.limit, `the compat layer grew to ${gz('dist/plainkit-compat.css').toFixed(2)} KB gzip, limit ${BUDGETS.compatCssGzKb.limit}: it only ever shrinks`);
    const modules = [...out.keys()].filter(f => /^dist\/elements\/[^/]+\.js$/.test(f) && !f.endsWith('registry.js'));
    assert.ok(modules.length >= 6);
    for (const f of modules) assert.ok(gz(f) <= BUDGETS.elementGzKb.limit, `${f} is ${gz(f).toFixed(2)} KB gzip, limit ${BUDGETS.elementGzKb.limit}`);
});

test('the element base runtime stays inside its budget', () => {
    const strip = t => t.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '').replace(/\n\s+/g, '\n').replace(/\n+/g, '\n');
    const kb = ['js/element.js', 'js/element-core.js'].reduce((n, f) => n + gzKb(strip(read(f))), 0);
    assert.ok(kb <= BUDGETS.baseRuntimeGzKb.limit, `base runtime is ${kb.toFixed(2)} KB gzip, limit ${BUDGETS.baseRuntimeGzKb.limit}`);
});

test('every behaviour module stays inside the per-module gzip budget and the base set stays small', () => {
    const modules = ['components/modal/modal', 'components/tabs/tabs', 'components/topbar/topbar', 'components/workspace/workspace', 'components/nav/nav', 'js/theme', 'js/colour', 'js/quality', 'js/scoring', 'js/audit', 'js/plainkit', 'js/code-explorer/element', 'js/code-explorer/providers', 'js/code-explorer/tokenize'];
    for (const m of modules) assert.ok(gzKb(read(`${m}.js`)) < BUDGETS.jsModuleGzKb.limit, `${m}.js is over ${BUDGETS.jsModuleGzKb.limit} KB gzip`);
    const base = ['components/modal/modal', 'components/tabs/tabs', 'components/topbar/topbar', 'components/workspace/workspace', 'components/nav/nav', 'js/theme', 'js/colour', 'js/plainkit'].map(m => read(`${m}.js`)).join('');
    assert.ok(gzKb(base) < BUDGETS.baseJsGzKb.limit, 'the base script set grew past its budget');
});

test('the static score never drops below the recorded baseline (it only goes up)', () => {
    const baseline = JSON.parse(read('site/scorecard/baseline.json'));
    const { scores } = runStaticAudit();
    assert.ok(scores.overall >= baseline.overall, `static overall ${scores.overall} is below the baseline ${baseline.overall}`);
    for (const [k, v] of Object.entries(baseline.categories)) if (v !== null) assert.ok(scores.categories[k].score >= v, `${k} dropped from ${v} to ${scores.categories[k].score}`);
