// The repository is public: nothing in it may carry a private tracker reference, a personal absolute path, a real-looking email address or
// stale "proprietary" licence text. This scans every text file under core/ (generated dist and the Files snapshot included, because they
// are published too) and the repository's own docs. Generic patterns only: naming a private project here would leak it.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const core = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const repo = path.resolve(core, '..');
const SKIP_DIRS = new Set(['node_modules', '.git', 'bin', 'obj']);
const TEXT = /\.(html|css|js|mjs|json|md|svg|yml|yaml|cs|razor|csproj|props|slnx|txt)$/;
// Files that must name these patterns to police them.
const SELF = new Set(['core/tests/privacy.test.mjs', 'core/tools/security.mjs', 'core/tests/security.test.mjs', 'core/tests/carveout.test.mjs']);

function walk(dir) {
    return fs.readdirSync(dir, { withFileTypes: true }).flatMap(e => (e.isDirectory() ? (SKIP_DIRS.has(e.name) ? [] : walk(path.join(dir, e.name))) : [path.join(dir, e.name)]));
}
const files = [...walk(core), ...fs.readdirSync(repo).filter(f => /\.(md|props|slnx)$/.test(f)).map(f => path.join(repo, f))]
    .filter(f => TEXT.test(f) && !SELF.has(path.relative(repo, f).split(path.sep).join('/')));

function scan(pattern, allow = () => false) {
    const hits = [];
    for (const f of files) {
        const lines = fs.readFileSync(f, 'utf8').split('\n');
        lines.forEach((l, i) => { for (const m of l.matchAll(pattern)) if (!allow(m[0], l)) hits.push(`${path.relative(repo, f).split(path.sep).join('/')}:${i + 1}: ${m[0]}`); });
    }
    return hits;
}

test('no internal tracker references (a letter T, a hyphen and a number)', () => {
    assert.deepEqual(scan(/\bT-\d{2,4}\b/g), []);
});

test('no personal absolute paths', () => {
    assert.deepEqual(scan(/[A-Za-z]:[\\/]{1,4}Users[\\/]{1,4}[A-Za-z]|\/Users\/[a-z][\w.-]*\/|\/home\/[a-z][\w.-]*\//g), []);
});

test('no real-looking email addresses (example, localhost and noreply placeholders are fine)', () => {
    const ok = m => /@(example\.(com|org|net)|localhost|plainkit\.invalid|w3\.org)$/i.test(m) || /^(name|user|you|me|hello|info|test)@/i.test(m);
    assert.deepEqual(scan(/[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}/g, ok), []);
});

test('no stale proprietary licence text: the repository is MIT', () => {
    assert.deepEqual(scan(/proprietary, part of the reposito[r]y/gi), []);
});

// Samples and layers: every sample sits in its own folder with a meta file whose component list is true, and the top level is the
// documented set of layers.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadSamples, SAMPLE_GROUPS, loadComponents } from '../tools/build.mjs';
import { classOwners, usedComponents, elementFolders } from '../tools/usage.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const read = f => fs.readFileSync(path.join(root, f), 'utf8').replace(/\r\n/g, '\n');
const owners = classOwners(root);
const elementNames = elementFolders(root);
const componentNames = new Set([...loadComponents().map(c => c.name), ...elementNames]);

test('the top level holds only the documented layers and entry files', () => {
    const allowed = new Set(['tokens', 'base', 'elements', 'components', 'layouts', 'samples', 'js', 'modules', 'site', 'tools', 'tests', 'dist', 'README.md', 'LICENSE', 'package.json', 'HANDOFF.md', 'STANDARDS.md', 'index.html', 'icons.svg', 'plainkit.css']);
    const extra = fs.readdirSync(root).filter(n => !allowed.has(n));
    assert.deepEqual(extra, [], 'a new top-level entry needs a place in the layer list (README and STANDARDS.md)');
});

test('every sample is a folder with html and meta, and its meta names the components its markup uses', () => {
    const problems = [];
    for (const [group, dir] of SAMPLE_GROUPS) {
        const base = path.join(root, dir);
        const folders = fs.readdirSync(base, { withFileTypes: true }).filter(e => e.isDirectory()).map(e => e.name);
        assert.ok(folders.length >= (group === 'patterns' ? 6 : 5), `${dir} has ${folders.length} samples`);
        for (const id of folders) {
            const meta = JSON.parse(read(`${dir}/${id}/${id}.meta.json`));
            const markup = ['html', 'js'].map(e => (fs.existsSync(path.join(base, id, `${id}.${e}`)) ? read(`${dir}/${id}/${id}.${e}`) : '')).join('\n');
            if (meta.id !== id) problems.push(`${dir}/${id}: meta.id is ${meta.id}`);
            for (const k of ['title', 'summary', 'used', 'order']) if (meta[k] === undefined) problems.push(`${dir}/${id}: meta lacks ${k}`);
            for (const u of meta.used ?? []) if (!componentNames.has(u)) problems.push(`${dir}/${id}: unknown component ${u}`);
            const actual = usedComponents(markup, owners, elementNames);
            if (JSON.stringify(actual) !== JSON.stringify(meta.used)) problems.push(`${dir}/${id}: used should be ${JSON.stringify(actual)}`);
        }
    }
    assert.deepEqual(problems, []);
});

test('loadSamples returns the three groups in order with their html', () => {
